    'grant_or_revoke_app_and_webhook_access_to_shared_user_p_3d751497' => 'Предоставяне или отнемане на достъп на приложения и webhook-и до споделени потребителски предпочитания и пространства от имена на частни метаданни.',
    'list_this_environment_s_webhook_endpoints_where_they_po_50897ffc' => 'Преглед на крайните точки за webhook-и в тази среда: адреси, абонирани събития и дали са на пауза — никога тайните им за подписване.',
    'list_the_hooks_called_during_sign_in_and_token_issuance_563aad82' => 'Преглед на hook-овете, извиквани при вход и издаване на токени, и дали всеки е активен.',
    'list_the_siem_destinations_this_environment_s_audit_tra_fe43c8df' => 'Преглед на SIEM дестинациите, към които се предава одитната следа на тази среда, и дали всяка е активирана.',
    'read_this_environment_s_domain_events_the_same_events_w_a994d958' => 'Четене на домейн събитията на тази среда — същите, които webhook-ите доставят — чрез курсор.',
    'read_this_environment_s_audit_trail_who_did_what_to_wha_3e0d9fc8' => 'Четене на одитната следа на тази среда: кой какво е направил, с кой обект и кога.',
    'register_repoint_pause_resume_re_key_and_delete_webhook_59f2b3cf' => 'Регистриране, пренасочване, спиране, възобновяване, смяна на ключове и изтриване на крайни точки за webhook-и. Новата или подменена тайна за подписване се показва само веднъж.',
    'register_pause_activate_and_remove_hooks_endpoints_that_17dc8c62' => 'Регистриране, спиране, активиране и премахване на hook-ове — крайни точки, които могат да добавят атрибути към токени или да откажат вход.',
    'create_disable_resume_and_delete_audit_log_streams_a_ge_d507a36c' => 'Създаване, деактивиране, възобновяване и изтриване на потоци от одитни записи. Генерираният ключ за подписване се показва само веднъж.',
    'record_audit_events_your_app_s_users_cause_for_the_orga_a94adc1d' => 'Записване на одитни събития, предизвикани от потребителите на приложението ви, за организациите, в които се случват. Само необходимите права за бекенд, който изпраща събития.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Четене на одитните събития, изпратени от приложението ви, и техните експорти, проверка на веригата на организация и преглед на схемите и правилата за съхранението им.',
    'start_csv_exports_of_the_audit_events_your_app_sent_the_230b66c5' => 'Стартиране на CSV експорти на одитните събития, изпратени от приложението ви — същите събития, достъпни с обхвата за четене, в един файл.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Определяне, подмяна и изтриване на схемите за валидиране на одитни събития и промяна на срока им за съхранение — съкращаването му изтрива по-старите събития завинаги.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Четене на схемата за упълномощаване и нейните кортежи, проверки и заявки за списъци — „Може ли този потребител да редактира този документ?“, „Кои документи може да вижда?“. Само необходимите права за бекенда на приложение да прилага правилата за достъп.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Записване и изтриване на кортежи на връзки — кой притежава, редактира или вижда кои ресурси на приложението ви. Записването веднага предоставя или отнема достъп в приложението.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Подмяна на схемата за упълномощаване — типовете ресурси и начина на определяне на всяка връзка. Променя незабавно отговора на всяка проверка в тази среда.',
    'read_the_authentication_policy_the_social_login_provide_758352e3' => 'Четене на политиката за удостоверяване, доставчиците за вход чрез социални профили и декларацията за наследен вход — никога тайната на доставчик.',
    'change_password_mfa_and_sso_rules_self_service_sign_up_66c7cb03' => 'Промяна на правилата за пароли, MFA и SSO, самостоятелната регистрация, доставчиците за вход чрез социални профили и одобрението на наследен вход.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Преглед на режима на Radar, вградените и персонализираните правила, списъците за разрешаване и блокиране и прегледа на решенията — защо вход или регистрация са разрешени, подложени на допълнителна проверка или блокирани. Никога IP или друг адрес от решение.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Създаване, пренареждане и изтриване на правила на Radar, настройване на вградените правила и добавяне или премахване на записи в списъците за разрешаване и блокиране.',
    'switch_radar_between_monitor_record_only_and_enforce_bl_c3ec2073' => 'Превключване на Radar между наблюдение (само записване) и прилагане (блокиране и допълнителни проверки) — включване или изключване на защитата при вход в средата.',
    'list_the_publishable_keys_browser_apps_present_to_the_f_9a4fe3ce' => 'Преглед на публикуемите ключове, които браузърните приложения подават към Frontend API, и разрешените им източници.',
    'create_publishable_keys_change_which_origins_may_presen_79684ec2' => 'Създаване на публикуеми ключове, промяна на източниците, които могат да ги подават, и отмяната им.',
    'list_the_applications_that_trust_this_environment_as_th_61538b0b' => 'Преглед на приложенията, които се доверяват на тази среда като доставчик на самоличност по SAML — никога техните сертификати.',
    'register_change_and_remove_the_applications_people_sign_6b6a4041' => 'Регистриране, промяна и премахване на приложенията, в които потребителите влизат с профила си тук.',
    'read_the_hosted_sign_in_theme_and_branding_of_the_envir_c85a3622' => 'Преглед на темата и визуалната идентичност на хостваната страница за вход на средата и нейните организации.',
    'change_the_hosted_sign_in_theme_and_branding_of_the_env_bc832c7e' => 'Промяна на темата и визуалната идентичност на хостваната страница за вход на средата и нейните организации.',
    'read_this_environment_s_custom_domain_and_the_dns_recor_4408e8a7' => 'Преглед на персонализирания домейн на тази среда и DNS записа, който го потвърждава.',
    'add_verify_and_remove_the_custom_domain_this_environmen_9a4835eb' => 'Добавяне, проверка и премахване на персонализирания домейн, на който е достъпна тази среда.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Окончателно изтриване на лице (чл. 17 от ОРЗД): неговите идентификационни данни, сесии, членства и лични данни се изтриват, а профилът се псевдонимизира. Действието е необратимо.',
    'create_rename_re_permission_and_delete_roles_and_author_dca95601' => 'Създаване, преименуване, промяна на разрешенията и изтриване на роли и определяне на ръчните разрешения, които ги съставят. Предоставянето на роли на хора изисква `roles:write`.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Преглед на SAML и OIDC връзките, чрез които организациите влизат, и имейл домейните, които насочват хората към тях — никога сертификат, клиентска тайна или ключ за подписване.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Създаване, промяна, активиране, деактивиране и изтриване на SSO връзки, изискване на SSO за организация и проверка на имейл домейните ѝ с налагане на SSO за тях. Променя начина на вход на хората.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Преглед на директориите (SCIM, Google Workspace, Microsoft Entra), които синхронизират потребители към средата, техните групи и грешки при синхронизация — никога bearer токен или идентификационни данни на доставчик.',
    'connect_rename_pause_re_key_and_delete_inbound_director_9cb4cce4' => 'Свързване, преименуване, спиране, смяна на ключове и изтриване на входящи директории и съпоставяне на групите им с роли. Новият или подменен SCIM bearer токен се показва само веднъж.',
    'list_the_downstream_scim_targets_this_environment_pushe_2753c203' => 'Преглед на целевите SCIM системи, към които тази среда изпраща потребители, и дали някоя има грешки — никога идентификационните им данни.',
    'register_pause_resume_and_delete_the_scim_targets_this_ca3c3bb1' => 'Регистриране, спиране, възобновяване и изтриване на SCIM дестинациите, към които тази среда изпраща данни за хора.',
    'read_role_conflict_segregation_of_duties_rules_and_acce_8572d9a3' => 'Четене на правилата за конфликт на роли (разделение на задълженията) и прегледите на достъпа с всеки елемент, за който се изисква потвърждение.',
    'define_switch_and_remove_role_conflict_rules_open_acces_34e40e6c' => 'Определяне, включване, изключване и премахване на правила за конфликт на роли; започване на прегледи на достъпа, записване на решения и приключване — приключването прилага всяко отнемане на достъп.',
    'list_the_downstream_credentials_stored_in_the_token_vau_15a080ce' => 'Преглед на идентификационните данни за външни системи, съхранени в хранилището за токени, и кои приложения могат да получат временен достъп до всяко — никога съхранените стойности.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Съхраняване, ротация и отмяна на идентификационни данни за външни системи и предоставяне или отнемане на правото на приложение за временен достъп до тях. Това не са обхватите vault.manage / vault.lease в собствения токен на приложението.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Преглед на флаговете за функции и тяхното насочване и оценяване на всеки флаг за потребител в организация — това, което бекендът на приложение заявява, когато няма токен.',
    'define_switch_retarget_and_delete_feature_flags_which_f_e64692af' => 'Определяне, превключване, промяна на насочването и изтриване на флагове за функции — кои функции получават кои потребители и организации.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Преглед на външните доставчици, към които хората могат да свържат профилите си, приложенията с право на временен достъп до тези токени и кой се е свързал — никога клиентска тайна или токен.',
    'configure_change_and_remove_pipes_grant_or_withdraw_an_f69a04e9' => 'Конфигуриране, промяна и премахване на pipes, предоставяне или отнемане на правото на приложение за временен достъп до токените на свързани профили и разкачване на потребителски профил.',
    'list_an_organization_s_recent_admin_portal_links_what_e_f1c55153' => 'Преглед на скорошните връзки към Администраторския портал на организация: какво отварят, кой ги е създал, на кого са изпратени и какъв е статусът им — никога самата връзка.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Създаване и оттегляне на еднократна връзка към Администраторския портал, която позволява на ИТ администратора на организация да настрои SSO, домейни или синхронизация на директории без профил. Новата връзка се показва само веднъж.',
    'list_the_pending_requests_from_agents_to_act_as_one_of_67e57ec8' => 'Преглед на чакащите заявки от агенти да действат от името на човек в тази среда (OIDC CIBA): кое приложение, за кого и какво иска.',
