    'framework_2b522c10efd9' => ':where наследява чрез `:value2`, което изброява потребителското множество `:value3`; връзка, чрез която се наследява, може да изброява само типове като `[folder]`.',
    'framework_0ead505bb5da' => ':where наследява `:value2` от `:value3`, но никой тип, към който сочи `:value4`, не дефинира `:value5`.',
