    'framework_8038ba872fa4' => 'Обхватът [:key] не е валиден идентификатор на обхват (RFC 6749 §3.3: печатаем ASCII, без интервали, кавички или обратни наклонени черти, до 128 знака).',
    'framework_918e4c13cded' => 'Обхватът [:key] е дефиниран от самия сървър за упълномощаване и не може да принадлежи на API.',
    'framework_43fd205dea6a' => 'Обхватът [:key] вече принадлежи на друг API в тази среда. Ключовете на обхватите са уникални за всяка среда, защото заявката за токен посочва обхват само чрез ключа му.',
    'framework_632573ec7b49' => 'Приложението [:clientId] трябва да има същия собственик като API, чийто достъп контролира. Свързването би включило ролите и разрешенията на един собственик в токените на друг.',
    'framework_f94b33602fbd' => '[:input] не е използваем източник. Посочете схема и хост без път — например https://app.acme.com или http://localhost:3000 при разработка.',
