    'framework_e23a74472a6b' => 'Проектът [:projectId] достигна лимита за среди на своя план: :limit.',
    'framework_1845262d35d9' => 'Заявените обхвати принадлежат на повече от един API (:value1). Посочете за кой API е токенът чрез параметъра resource.',
