    'framework_92a2cb6cba31' => 'Този токен за опресняване е обвързан с ресурс, различен от заявения.',
    'framework_78e3d61edb93' => 'Клиентът [:clientId] е публичен: използва PKCE и няма тайна.',
    'framework_4a882cbbcad9' => 'Клиентът [:clientId] се удостоверява със собствени ключове (private_key_jwt) и няма тайна. Вместо това подменете ключа в неговия набор JWK.',
    'framework_fc1964a8e8c4' => 'Това е последната активна тайна на клиента [:clientId]. Подменете я чрез ротация; отмяната ѝ би попречила на клиента да се удостоверява.',
    'framework_0ffaaa599a0c' => 'Гратисният период при ротация трябва да е между 0 и :max секунди; подадено е :grace.',
    'framework_3cf574caed49' => 'Обхватите :value1 принадлежат на регистриран API, чиито обхвати този клиент не може да има. Клиент на организация може да има обхвати на API на собствената си организация и обхватите на API на средата, които организациите имат право да заявяват.',
    'framework_2cb3fdf8752f' => 'Сесията за поддръжка не може да е за човека, който я започва.',
    'framework_c36f61e55547' => 'Сесиите за поддръжка са достъпни само за собствени приложения на средата, които използват потока с код за упълномощаване.',
