    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Кодът може да бъде откраднат чрез подмяна на SIM карта или неразрешено прехвърляне на номера, прихванат в телефонната мрежа или въведен в убедителна фалшива страница за вход. Все пак е много по-добре от само парола — включете го за хора, които не могат да използват приложение за удостоверяване или ключ за достъп.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Лого, зареждано от друг сайт, съобщаваше на този сайт за всеки човек, отворил страницата ви за вход. Затова хостваните страници вече показват само изображения, качени тук. Качете логото по-долу в :part2 или го премахнете, за да скриете това съобщение.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 може да влиза с пароли или чрез тази връзка. Изискването за единен вход отхвърля всички други начини за достъп, така че нищо вече издадено не може да заобиколи току-що настроения доставчик. Повечето компании, които свързват IdP, искат това — но първо прочетете последствията.',
