    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 Ролята е етикет, включен в токена — ролите, декларирани от приложение, тук са само за четене, а останалите определяте вие. :part2 :part3 :part4 — всеки член има и точно една такава роля (Собственик, Администратор, Разработчик, Член или Наблюдател), която определя какво може да администрира в тази конзола.',
