    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Флагът за функционалност е превключвател, чието състояние приложенията проверяват за конкретен човек в организация. Активирайте го за избрани потребители, организации или процент от всички потребители. Всяко приложение получава един и същ отговор в полето `feature_flags` на токена или от крайната точка за оценяване, без ново внедряване. Правилото за потребител има предимство пред това за организация, то пред постепенното включване, а то пред стойността по подразбиране.',
