    'it_stops_working_immediately_anything_still_using_it_fa_4a9caff7' => 'Спира да работи незабавно. Всичко, което все още го използва, няма да може да влиза.',
    'it_uses_pkce_and_gets_no_secret_nothing_to_l_f9fee647' => 'Използва PKCE и не получава тайна — няма какво да изтече от браузър или телефон.',
    'its_events_are_accepted_unchecked_from_now_on_or_refuse_af37acad' => 'Отсега събитията му се приемат без проверка — или се отхвърлят, ако строгият режим е включен.',
    'its_members_can_sign_in_again_and_its_environments_resu_d369bd33' => 'Членовете му могат отново да влизат, а средите му възобновяват удостоверяването.',
    'its_own_credentials_in_place_of_the_environment_s_for_t_bf11c9ef' => 'Собствени идентификационни данни вместо тези на средата за този доставчик.',
    'key_created_paste_it_into_your_frontend_it_is_meant_to_0e59b7a5' => 'Ключът е създаден. Поставете го във фронтенда — предназначен е да е публичен.',
    'key_rotated_copy_the_new_one_now_the_old_key_keeps_work_aedb1c3d' => 'Ключът е сменен — копирайте новия сега. Старият ключ продължава да работи 24 часа.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Показва бутони за Google, GitHub, Apple и други доставчици на страницата за вход за хората, които предпочитат съществуващ акаунт пред нова парола. Настройте доставчика веднъж за средата и той ще е достъпен за всички организации. Организацията може да използва собствени данни за достъп или да изключи доставчик. Въвеждате данните за достъп, а останалото се попълва автоматично. Само адресът, изпратен от доставчика, никога не е достатъчен за достъп до съществуващ тук акаунт.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Ключовете, с които кодът ви се удостоверява пред Cbox ID, с отделен раздел за всеки вид. Секретният ключ, наричан и ключ за управление, позволява на backend системата да управлява организациите, членовете, поканите, ролите и приложенията в една среда. Ключът за организация извиква нейния API с вградена роля. Публичният ключ се използва в приложение в браузъра и работи само от разрешените източници. Секретните ключове и ключовете за организация се показват само веднъж. Копирайте ги при създаване и ги отменете незабавно при изтичане.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Регистрира приложения, които приемат тази среда за SAML доставчик на идентичност, така че потребителите влизат със съществуващите си тук акаунти. Свържете всяко приложение с неговата организация, за да могат да влизат само нейните членове. Без свързана организация приложението е достъпно за всички потребители в средата. Това е изходящата посока. За вход с фирмен акаунт от друга система използвайте Корпоративен SSO в раздел Удостоверяване.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Изберете framework, с който разработвате. Създава се приложение с пренасочване към локалния сървър за разработка, блок с конфигурация на средата за поставяне и код за вход на потребител. Страницата изчаква реално влизане. По-долу са стъпките за подготовка на продукта: брандиране, организации, единен вход, агент, колега и продукционна среда. Завършването им се отбелязва според действителното състояние на средата, никога ръчно.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar оценява всяко влизане и регистрация: опити с откраднати данни за вход, скорост, характерна за ботове, невъзможни пътувания, нови устройства, анонимизиращи мрежи и еднократни адреси, както и собствените ви правила и списъци за разрешаване и блокиране. Записва всяко решение и след включване на прилагането блокира достъпа или изисква втори фактор. Прегледайте решенията тук преди включване на прилагането и когато някой не може да влезе.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Превключватели за функции, които приложенията проверяват за конкретен човек в организация. Включете функция за избрани потребители, организации или част от всички потребители. Всяко приложение чете един и същ отговор от токена или API.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Софтуер, който извършва действия в тази среда с ключ за управление: Claude Code, Cursor, вътрешен бот или вашият бекенд. Всеки разполага само с обхватите на достъп, които сте му дали, и изчаква одобрението ви там, където сте го изискали.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Получателят запазва същата тайна. Тайна от 64 шестнадесетични знака се преобразува в whsec_, последвано от base64 кодирането на този шестнадесетичен низ — "whsec_" + base64(secret). Тайна, която вече започва с whsec_, се използва без промяна.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Организации, потребители и активни сесии от всички среди в тази инсталация, както и организациите с най-много членове. Този изглед само чете данни и никога не променя средата, избрана в конзолата.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Всички, които могат да влизат в тази организация, и изпратените покани, които още не са приети. Канете хора по имейл; те сами настройват влизането си, така че никога не се налага да боравите с чужда парола.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Позволете на хората да влизат със съществуващ акаунт. Настройте доставчик веднъж за средата и той ще бъде достъпен във всички организации. Организацията може да използва собствени данни за достъп или да изключи доставчик.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar оценява всяко влизане и регистрация: опити с откраднати данни за вход, скорост, характерна за ботове, невъзможни придвижвания, нови устройства, анонимизиращи мрежи, временни адреси и вашите собствени правила и списъци. Записва и причината за решението.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Този потребител вече не може да влиза в никое приложение в тази среда, а съществуващите му сесии спират да работят при следващата заявка. Данните му се запазват и можете да го активирате отново по всяко време.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Оценява се последователно: списъкът за блокиране, списъкът с разрешения, вашите правила отгоре надолу (решава първото съвпадение), после вградените правила (решава най-строгото от задействаните). Ако няма съвпадение, достъпът се разрешава.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Повечето интеграции трябва да използват уебхукове: те се изпълняват след събитието и не могат да го забавят. Използвайте hook само когато вашата система трябва да участва в решението по време на влизане или издаване на токен.',
    'keys_you_create_appear_here_with_when_each_was_last_use_8c3ff766' => 'Тук се показват създадените от вас ключове и кога всеки е използван за последен път.',
    'leave_empty_for_no_lockout_this_deployment_has_switched_d1f1a3e9' => 'Оставете празно за липса на блокиране — в тази инсталация блокирането по подразбиране е изключено.',
