    '_owned_by_this_environment_not_by_this_organization_fir_33b76fa6' => '— принадлежи на тази среда, а не на тази организация. Собствените приложения на платформата се показват в менюто за приложения на всяка организация.',
    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => 'Обхватите :part1 принадлежат на API, който това приложение няма право да използва. Те се изключват от всеки токен; премахнете ги от ръчно въведените обхвати.',
