    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 все още няма разрешения, затова :part2 :part3 е празно. Името на ролята остава налично за проверка. :part4',
    '_part1_its_team_is_administered_under_organization_team_6abad4af' => ':part1 Екипът се управлява от „Организация › Екип“ от лице с роля в организацията, а не оттук.',
    '_part1_only_d798c565' => 'Само :part1',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Все още нищо тук не е зададено от :part3. Ако промените настройка по-долу, тя става собствено правило на тази организация.',
    '_part1_part2_only_5ce234b9' => 'Само :part1 :part2',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Полето :part2 има друго значение: то показва какво е имало право да поиска :part3 :part4, а не какво може да прави този :part5.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Изберете обхвата :part2 :part3 при регистриране на приложението. ID токенът ще съдържа същите имена на роли в полето :part4 — името, което очакват Kubernetes, Grafana и Vault. Не е нужно да създавате друго.',
    '_part1_validate_4be424e7' => ':part1 Проверете',
    '_part1_write_76920eab' => ':part1 Запишете',
    '_part1_write_a_permission_97ac7762' => ':part1 Създайте разрешение',
    '_the_platform_apps_below_belong_to_this_environment_rat_9f21136f' => ' Приложенията на платформата по-долу принадлежат на тази среда, а не на вас.',
    '_together_with_the_issuer_part1_because_the_app_also_si_e67abff1' => ', заедно с издателя :part1, защото приложението също извършва вход на потребители',
    'a_conflict_is_written_over_roles_so_there_is_nothing_to_1ee9ecc5' => 'Конфликтът се определя между роли, а все още няма роли, за които да се създаде. Първо определете ролите.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'Страница в :part1. Оставете празно, за да се отвори конзолата, като в поканата бъде посочено :part2.',
    'a_part1_key_you_can_compose_into_roles_e_g_part2_part3_2714a35b' => 'Ключ :part1, който можете да включвате в роли — например :part2. :part3 :part4',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'Разрешението определя какво може да прави :part1 след вход. Какво може да поиска :part2 се определя от обхвата на достъп, зададен при регистрирането в :part3 :part4.',
    'a_user_rule_beats_an_organization_rule_which_beats_the_74a29528' => 'Правило за потребител има предимство пред правило за организация, което има предимство пред процентното активиране, което има предимство пред стойността по подразбиране. Ако флагът е изключен, той е изключен за всички.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Достъпът се натрупва: хората сменят екипи, но запазват старите си права, и никой не забелязва до въпрос от одитор. Прегледът заснема текущото състояние на достъпа и изисква за всяко предоставяне да се потвърди дали още е необходимо.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Токените за достъп на това приложение посочват :part1 като получател :part2. API трябва да приема токен само ако е посочен като негов получател.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Токените за достъп на това приложение посочват издателя на тази среда, :part1 :part2, като получател. Това се променя, когато приложението получи обхват на достъп от някой от регистрираните ви API.',
    'acme_dashboard_0b433bd7' => 'Табло на Acme',
    'add_permissions_manually_3596f1b0' => 'добавяне на разрешения ръчно',
    'already_sent_try_again_in_seconds_seconds_and_check_the_e294712c' => 'Вече е изпратено. Време до следващия опит (сек): :seconds. Междувременно проверете папката за нежелана поща на получателя.',
    'an_app_registered_here_can_sign_your_people_in_and_read_f35bdb6c' => 'Регистрирано тук приложение може да вписва потребителите ви и да чете ролите им, така че управлявате достъпа на едно място, а не поотделно за всеки продукт.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'Приложението регистрира каталога си чрез SDK. :part1 :part2 Можете да създадете ролята сега и да добавите разрешенията, когато определенията им станат налични.',
    'an_owner_or_admin_can_add_sms_only_next_to_a_stronger_f_07347449' => 'Собственик или администратор може да добави SMS само заедно с по-силен фактор. Ако има само SMS, ще бъде помолен да добави такъв фактор.',
    'and_part1_more_1468d675' => 'и още :part1',
    'anyone_can_create_an_account_in_part1_and_becomes_the_o_ff47cb27' => 'Всеки може да създаде акаунт в :part1 и става собственик на собствена организация.',
    'apps_registered_by_the_organizations_in_this_environmen_1fd60d9d' => 'Този обхват на достъп може да се предоставя на приложения, регистрирани от организациите в тази среда. Оставете опцията изключена, ако обхватът е само за собствените ви приложения.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Приложенията насочват потребителите към регистрация с :part1 и молят вписан потребител да създаде организация с :part2. И двете са достъпни само докато тази настройка е включена.',
    'apps_that_hold_it_keep_it_as_a_typed_scope_which_no_lon_6498e819' => 'Приложенията го запазват като ръчно въведен обхват на достъп, който вече не дава достъп до този API. Токените спират да го включват за този получател.',
    'ask_a_sign_up_radar_flags_to_prove_it_is_a_person_cloud_5b5f2963' => 'Изисквайте регистрациите, маркирани от Radar, да докажат, че са от човек чрез Cloudflare Turnstile. Ако е изключено, вместо това се изисква потвърждение на имейл адреса.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'Заявката е точно такава, каквато я изпраща приложението ви (:part1), с всички наследявания, определени от схемата.',
    'at_least_as_fresh_as_bb83225d' => 'Поне толкова актуално, колкото',
    'built_in_role_for_part1_de8e2bb3' => 'Вградена роля за :part1',
    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Потвърдете това, което още е необходимо, и отнемете ненужното. Нищо не влиза в сила до приключването на прегледа; тогава отнетата роля за администрация и поддръжка се премахва във всички организации наведнъж.',
    'choose_one_of_roles_ownership_is_handed_over_with_trans_90a222bb' => 'Изберете една от ролите: :roles. Собствеността се предава чрез „Прехвърляне на собственост“, никога чрез покана.',
    'close_it_every_revoke_is_applied_for_real_and_anything_b4db8386' => 'Приключете прегледа. Всички отнемания се прилагат реално, а непрегледаните записи следват политиката на прегледа.',
    'comma_or_space_separated_a_scope_you_type_is_unowned_it_c5513416' => 'Разделяйте със запетаи или интервали. Въведен ръчно обхват няма собственик: влиза в токените на приложението без промяна, но никога не може да им добави целевата аудитория на регистриран API. За това използвайте списъците по-горе.',
    'comma_separated_only_for_keys_this_catalogue_5b436f7f' => 'Разделени със запетаи. Само за ключове, които не се предлагат в този каталог.',
    'count_rollout_a202cfc4' => 'Активиране за :count%',
    'create_a_new_client_secret_choose_how_long_the_current_7788f8af' => 'Създайте нова клиентска тайна. Изберете колко дълго да работи текущата, за да могат всички инсталации да преминат към новата навреме.',
    'decided_by_this_deployment_s_cbox_id_signup_mode_which_5691d2c8' => 'Определя се от CBOX_ID_SIGNUP_MODE на тази инсталация, със стойност „:part1“. Състояние на регистрацията: :part2.',
    'declare_the_roles_that_must_never_sit_with_the_same_per_00379b41' => 'Определете ролите, които едно лице никога не трябва да притежава едновременно — разделение на задълженията — и вижте кой вече има конфликтна двойка.',
    'default_part1_a0a77763' => 'По подразбиране: :part1',
    'defined_for_the_whole_environment_every_organization_ca_8039a976' => 'Определена за цялата среда: всяка организация може да я използва. Само този вид роля може да се даде на човек във всички организации наведнъж.',
    'each_new_account_creates_its_own_organization_and_owns_3528fda3' => 'Всеки нов акаунт създава и притежава собствена организация. Приложенията могат също да поискат от вписан потребител да създаде организация с :part1 :part2.',
    'enterprise_sso_part1_ef8e20aa' => 'Корпоративен SSO :part1',
    'environment_default_part1_you_can_require_more_not_fewe_8d900b4b' => 'Стойност по подразбиране за средата: :part1. Можете да изисквате повече, но не по-малко.',
    'every_api_key_the_people_in_this_organization_have_crea_b802c1e7' => 'Всички API ключове, създадени от хората в тази организация за нейните приложения. Отменете ключ, който е изтекъл или вече не се използва. Хората създават собствени ключове в „Моят акаунт“.',
    'every_logout_token_then_names_the_session_si_54d0a907' => 'Всеки токен за изход тогава посочва сесията (sid), както и лицето, така че приложението да може да прекрати само тази сесия, а не всички негови сесии.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Всички отнемания, записани в този преглед, се прилагат действително сега. Непрегледаните елементи следват политиката на прегледа, която по подразбиране отнема достъпа. Това действие не може да бъде отменено.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Всички тайни, които в момента удостоверяват това приложение. Съхранява се само хешът на всяка. Списъкът показва последните четири знака, за да разпознаете коя тайна използва дадена инсталация.',
    'every_text_costs_money_codes_go_only_to_the__171894a6' => 'Всяко текстово съобщение струва пари. Кодовете се изпращат само до държавите по-долу. За всеки номер, мрежов адрес и тази среда има дневни ограничения.',
    'everyone_in_this_organization_and_their_roles_one_built_35d8fefb' => 'Всички в тази организация и техните роли: по една вградена роля и допълнителни роли на приложения или персонализирани роли',
    'everything_a_role_can_be_allowed_to_do_write_your_own_b_233ea6c4' => 'Всички действия, които могат да бъдат разрешени на роля. Определете свои по-долу без код или оставете приложенията да ги регистрират автоматично.',
    'face_id_touch_id_windows_hello_or_a_security_key_turnin_6e23006c' => 'Face ID, Touch ID, Windows Hello или ключ за сигурност. Изключването запазва вече добавените ключове за достъп, за да могат да се използват при повторно включване.',
    'filter_the_list_to_one_organization_to_scan_it_for_peop_6dbcc13b' => 'Ограничете списъка до една организация, за да проверите кои хора вече имат конфликтна двойка роли. Все още не е извършена проверка.',
    'for_a_secret_that_has_leaked_anything_still_using_it_fa_7b1c0246' => 'За тайна, която е разкрита. Всичко, което още я използва, спира да работи веднага.',
    'for_development_refused_on_anything_but_the_origins_you_113f24ad' => 'За разработка. Отхвърля се от всички източници, които не сте посочили, както при продукционните ключове.',
    'give_your_app_the_feature_flags_scope_and_read_the_feat_a6908f11' => 'Предоставете на приложението обхвата на достъп feature_flags и прочетете полето feature_flags от токена му.',
    'give_your_apps_those_scopes_on_their_scopes_tab_tokens_97d115cd' => 'Предоставете тези обхвати на достъп на приложенията от раздела „Обхвати“. Токените им посочват API като получател.',
    'grants_that_would_break_this_rule_are_blocked_from_now_1454bf59' => 'Отсега нататък се блокират назначения, които нарушават това правило. Хората, които вече имат двойката роли, я запазват. Проверката по-горе ви помага да ги откриете.',
    'have_the_app_declare_the_roles_it_understands_so_you_ca_9074afe0' => 'Нека приложението декларира ролите, които разбира, за да можете да ги назначавате тук.',
    'holds_conflicting_roles_part1_part2_23b385ca' => 'Има конфликтни роли: :part1 :part2',
    'holds_part1_part2_6b1a0140' => 'Има: :part1 :part2',
    'how_an_app_connects_is_fixed_at_registration_changing_i_0372baec' => 'Начинът на свързване на приложението се определя при регистрацията. Промяната му би променила значението на удостоверителните данни, затова регистрирайте ново приложение, вместо да променяте предназначението на това.',
    'how_long_an_access_token_for_this_app_is_acc_22748384' => 'Колко дълго се приема токенът за достъп на това приложение. По-кратката валидност ограничава времето, през което приложение, проверяващо токените офлайн, може да приема отменен токен. Приложенията, използващи интроспекция, могат да установят отмяната веднага. Токените за обновяване поддържат сесиите на хората между подновяванията на токените за достъп.',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Начините за вход в :part1. Започват със стойностите по подразбиране на средата. Промените тук могат само да ги направят по-строги.',
    'inherited_46b2e93c' => 'наследено',
    'its_rules_go_with_it_apps_asking_for_its_key_get_off_fr_aacd29e9' => 'Правилата се премахват заедно с него. Приложенията, които заявяват ключа му, отсега нататък получават изключена стойност. Вече издадените токени продължават да го посочват до изтичането си.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Обхватите на достъп се премахват заедно с него. Приложенията ги запазват като ръчно въведени обхвати, които вече не дават достъп до този API. Вече издадените токени остават валидни до изтичането си.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Ключове за API за управление на среда: управлявайте организациите, членовете, поканите, ролите и приложенията в една среда от собствения си бекенд. Всеки ключ има изрично зададени обхвати на достъп.',
    'keys_your_browser_side_app_presents_to_the_frontend_api_ff8c1e2c' => 'Ключове, които браузърното ви приложение представя на Frontend API. Те се включват в JavaScript пакета. Защитата е списъкът с разрешени източници, а не самият ключ.',
    'leave_empty_for_this_deployment_s_default_of_part1_f391c886' => 'Оставете празно, за да използвате стойността по подразбиране на инсталацията: :part1.',
    'leave_empty_for_this_install_s_default_value_fda04f89' => 'Оставете празно за стойността по подразбиране на инсталацията. Стойност по подразбиране (минути): :value0. Максимум, зададен от оператора (минути): :value1.',
    'let_your_apps_declare_the_roles_they_understand_those_a_719f1d4a' => 'Нека приложенията декларират ролите, които разбират. Те се появяват тук автоматично.',
    'lets_the_people_who_use_this_app_create_api__6ef80e45' => 'Позволява на потребителите на приложението да създават ключове за неговия API в Моят акаунт › API ключове. Всеки ключ е свързан с човека, една организация и подмножество от разрешенията му в приложението. API проверява ключа чрез извикване на Cbox ID с данните за достъп на самото приложение. Ключът губи разрешение веднага щом притежателят му го загуби.',
    'lets_this_app_trade_a_token_it_was_given_for_e3add8e6' => 'Позволява на това приложение да замени получен токен с такъв за друга ваша услуга, с по-ограничени права или друг получател, чрез стандартния механизъм token-exchange (RFC 8693). Включете за сървърно приложение, което извиква други услуги от името на човек.',
    'line_part1_8c02d91a' => 'Ред :part1: ',
    'list_the_origins_it_may_be_presented_from_one_per_line_76b78615' => 'Избройте източниците, от които може да се представя — по един на ред, включително протокола.',
