    'the_environment_s_administrators_register_apis_and_deci_eb40bdf1' => 'Администраторите на средата регистрират API и решават кои от техните обхвати на достъп могат да заявяват приложенията ви.',
    'the_facts_your_app_wrote_what_they_add_up_to_is_what_a_3240d92d' => 'Фактите, записани от приложението ви. Проверката показва какви права произтичат от тях.',
    'the_key_can_do_only_what_its_scopes_allow_read_never_im_78fe4757' => 'Ключът може да прави само това, което обхватите му на достъп позволяват. Правото за четене никога не дава право за запис.',
    'the_key_holds_the_built_in_role_you_choose_and_can_do_o_b7c48a4b' => 'Ключът притежава избраната вградена роля и може да прави само това, което тя позволява.',
    'the_kill_switch_off_the_flag_is_off_for_everyone_whatev_90bda36f' => 'Главен превключвател. Когато е изключен, флагът е изключен за всички, независимо от правилата по-долу.',
    'the_organization_the_app_belongs_to_or_regis_d0bd8e48' => 'Организацията, на която принадлежи приложението, или го регистрирайте към средата по-горе.',
    'the_return_address_must_be_on_one_of_app_s_registered_r_20ea9b1f' => 'Адресът за връщане трябва да е в един от регистрираните източници на URI за пренасочване на :app.',
    'the_rules_in_force_after_this_environment_s_baseline_is_278c536a' => 'Правилата в сила след прилагане на базовите правила на средата. Собствената настройка на организацията може само да ги затегне.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Вашите услуги, които получават токени за достъп, и обхватите на права, принадлежащи на всяка от тях. Вие разпределяте обхватите на регистриран API; никой не може да получи достъп до него, като просто впише обхват в приложение.',
    'the_organization_s_own_keys_for_the_organization_api_li_86017b30' => 'Собствените ключове на организацията за нейния API: списъци с проекти и среди, създаване на среди, списък с екипа и изпращане на покани. Всеки ключ има вградена роля.',
    'these_apply_to_every_organization_in_part1_not_only_par_ac56590d' => 'Те важат за всяка организация в :part1, не само за :part2.',
    'these_are_its_own_credentials_for_that_environment_s_co_a68e7d01' => 'Това са собствените му удостоверителни данни за настройките на онази среда. :part1',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Човекът става собственик на :part1, а вие ставате администратор. Само новият собственик може да ви върне собствеността.',
    'they_become_this_organization_s_only_owner_whoever_owns_11374c6d' => 'Човекът става единствен собственик на тази организация. Настоящият собственик става администратор.',
    'they_get_an_email_with_a_link_nothing_changes_until_the_e94c64b9' => 'Ще получат имейл с връзка. Нищо не се променя, докато не приемат.',
    'they_lose_access_to_this_organization_and_everything_it_984eedd8' => 'Губят достъп до тази организация и всички права, които тя дава. Самият акаунт не се променя.',
    'they_lose_every_role_and_application_this_organization_8c05da9e' => 'Губят веднага всички роли и приложения, предоставени им от тази организация.',
    'this_app_belongs_to_the_platform_and_is_available_to_ev_0c69cd5f' => 'Това приложение принадлежи на платформата и е достъпно за всяка организация в тази среда. Управлява се от оператора ви.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Това приложение има обхвати на достъп за повече от един API: :part1 :part2. Един токен е за един API наведнъж, затова приложението посочва желания API с параметъра :part3. Заявка за обхвати на достъп на два API едновременно се отхвърля.',
    'this_changes_permissions_for_all_current_holders_of_thi_a515eb89' => 'Това променя разрешенията на всички текущи притежатели на ролята. Не назначава ролята на нови хора.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Тази инсталация няма ключове за Turnstile (CBOX_ID_TURNSTILE_SITE_KEY), затова проверката не може да се включи. Маркираните регистрации вместо това потвърждават имейл адреса си.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Тази инсталация изпраща SMS само до следните държави: :part1. Номерата от следните държави не могат да получават кодове, докато държавите не бъдат включени в CBOX_ID_SMS_ALLOWED_COUNTRIES: :part2.',
    'this_environment_s_own_issuer_what_an_sdk_discovers_fro_b00e706b' => 'Собственият издател на тази среда — адресът, от който SDK открива настройките и който се съдържа в полето :part1.',
    'this_is_the_app_s_only_live_secret_so_it_cannot_be_revo_d05986bb' => 'Това е единственият активен таен ключ на приложението и не може да бъде отнет самостоятелно, защото приложението ще остане без начин за удостоверяване. Вместо това го сменете с нов.',
    'this_member_a802a70b' => 'този член',
    'this_organization_has_no_direct_role_or_membership_gran_1160edd2' => 'Тази организация няма преки назначения на роли или членства за потвърждаване.',
    'this_organization_owns_identity_providers_on_this_platf_f47c5479' => 'Тази организация притежава доставчици на идентичност на платформата. Първо затворете проектите ѝ в „Организация › Проекти“.',
    'this_organization_s_own_authentication_policy_is_droppe_a12f3b55' => 'Собствената политика за удостоверяване на организацията се премахва. Оттук нататък важат базовите правила на средата.',
    'this_permission_is_removed_from_every_role_that_current_d88d6738' => 'Това разрешение се премахва от всички роли, които го предоставят в момента. Това не може да се отмени.',
    'this_role_belongs_to_the_environment_and_applies_across_0a2b2ed6' => 'Тази роля принадлежи на средата и важи във всички нейни организации. Тя важи тук, но не можете да я променяте.',
    'this_role_grants_no_permissions_the_application_that_de_59b043d0' => 'Тази роля не дава разрешения. Приложението, което я декларира, определя какво може да прави тя.',
    'this_role_is_declared_by_an_application_which_is_its_so_03e7843e' => 'Тази роля се декларира от приложение, което е достоверният източник за нея. Не може да се редактира тук.',
    'this_rule_binds_every_organization_here_choose_one_in_t_9d1bbde3' => 'Това правило обвързва всяка организация тук. Изберете организация в заглавната част на конзолата, за да го проверите спрямо нейните назначения.',
    'this_rule_binds_every_organization_in_the_environment_i_91928f48' => 'Това правило обвързва всяка организация в средата. Показва се тук, защото ограничава и вашата. Управлява се от оператора ви.',
    'this_will_sign_people_out_of_part1_c2cac70c' => 'Това ще отпише потребителите от :part1',
    'to_register_an_api_for_one_organization_find_it_here_it_48b04329' => 'За да регистрирате API за една организация, намерете я тук. След това тя се предлага като собственик по-горе.',
    'tokens_stop_being_issued_for_this_audience_this_cannot_7912313c' => 'Спира издаването на токени за този получател. Това не може да се отмени.',
    'transfer_ownership_to_db1c7dbf' => 'Прехвърляне на собствеността към',
    'try_a_different_search_roles_already_ticked_stay_in_thi_82c5a227' => 'Опитайте друго търсене. Вече избраните роли остават в списъка независимо какво въвеждате.',
    'turn_it_on_for_a_beta_organization_a_few_users_or_a_per_bea36395' => 'Включете за тестова организация, няколко потребители или процент от всички.',
    'two_factor_authentication_part1_8c022f7b' => 'Двуфакторно удостоверяване :part1',
    'type_the_organization_s_name_exactly_as_shown_to_confir_f021127d' => 'Въведете името на организацията точно както е показано, за да потвърдите.',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Ръчно въведените обхвати на достъп (:part1) нямат собственик. Предават се без промяна и никога с регистриран API като получател.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Докато API не е регистриран, обхватът е само текст в приложение и всеки, който може да редактира приложението, може да му даде произволен обхват. Регистрирайте API, които приложенията ви извикват, за да имат обхватите им собственик.',
    'ux_advanced_help' => 'Незадължителни настройки. Стойностите по подразбиране са подходящи за повечето приложения.',
    'ux_scopes_summary' => 'Избрани разрешения: :count',
    'we_could_not_send_that_invitation_the_mail_server_refus_81a3f4df' => 'Не успяхме да изпратим поканата — пощенският сървър я отхвърли. Нищо не е създадено. Опитайте отново или проверете настройките за поща на инсталацията.',
    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Какво може да бъде позволено на приложение в този API. Тези обхвати на достъп могат да се предоставят само на приложения с този собственик: :part1.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Какво може да бъде позволено на приложение в този API. Собствените ви приложения могат да имат всички обхвати на достъп. Приложение, регистрирано от организация, може да има само отбелязаните за организации.',
    'what_apps_ask_for_such_as_invoices_read_unique_in_this_2109e70c' => 'Какво заявяват приложенията, например invoices:read. Трябва да е уникално в тази среда.',
    'what_people_can_do_inside_your_apps_you_assign_roles_he_c31f1a20' => 'Какво могат да правят хората във вашите приложения. Вие назначавате ролите тук, а всяко приложение определя какво позволяват неговите роли.',
    'what_this_role_is_allowed_to_do_tick_a_permission_to_gr_518298cc' => 'Какво позволява тази роля. Отбележете разрешение, за да го дадете, или махнете отметката, за да го отнемете.',
    'what_this_round_is_called_when_somebody_asks_which_revi_6e0713c0' => 'Името на този преглед, когато трябва да се установи откъде идва дадено решение — тримесечие, одит или дата.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'Какво заявява кодът ви и какво съдържа полето feature_flags. Малки букви и цифри, с - _ или . между тях. Не може да се променя по-късно.',
    'whatever_is_using_this_key_stops_working_immediately_th_8e55e6f5' => 'Всичко, което използва този ключ, спира да работи веднага. Това не може да се отмени.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_e14495d2' => 'Всичко, в което притежателят е включил този ключ, спира да работи веднага. Уведомете го предварително, ако можете. Това не може да се отмени.',
    'when_somebody_creates_an_api_key_for_one_of_your_apps_i_15c6370c' => 'Когато някой създаде API ключ за ваше приложение, той се появява тук заедно с притежателя и разрешените действия.',
    'when_somebody_signs_out_or_an_administrator__3520d247' => 'Когато някой излезе или администратор прекрати сесиите му, премахне го или го деактивира, Cbox ID изпраща подписан токен за изход на този адрес, директно между сървърите, за да може приложението също да прекрати собствената си сесия.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Мястото, към което Cbox ID насочва хората след изход от това приложение. URI, поискан от приложението, трябва да съвпада точно с посочен тук URI, включително крайната наклонена черта. В противен случай Cbox ID оставя човека на собствената си страница след изход. Оставете празно, ако приложението не пренасочва хората след изход.',
    'where_this_app_publishes_the_roles_it_unders_e6047562' => 'Къде приложението публикува поддържаните роли, за да могат да се задават тук.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Какви начини за вход предлага :part1 освен парола и колко дълго важи сесията. Те са еднакви за всички организации в средата.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Кой членува в тази организация и какво може да прави. Човек без акаунт тук получава покана по имейл.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Кой получава флага, когато никое правило не го посочва. Оставете изключено, за да активирате функцията първо за конкретни организации или процент от потребителите.',
    'whose_role_it_is_or_tick_the_box_above_to_define_it_for_970fb7fe' => 'На кого принадлежи ролята — или отбележете полето по-горе, за да я определите за всяка организация.',
    'whose_roles_and_memberships_the_review_snapshots_e7576353' => 'Чии роли и членства заснема прегледът.',
    'whose_rule_it_is_or_tick_the_box_above_to_apply_it_to_e_82370728' => 'На кого принадлежи правилото — или отбележете полето по-горе, за да важи за всяка организация.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Без роли всеки, който може да влиза, получава достъпа, който приложението дава на обикновен потребител. С роля определяте веднъж кои са редактори и кои са служители по поддръжката, а всички свързани приложения спазват това разпределение.',
    'work_through_the_list_certify_what_is_still_needed_revo_9bcc79ab' => 'Прегледайте списъка: потвърдете нужните права и отнемете ненужните.',
    'write_one_above_or_from_your_app_s_backend_in_batches_o_9ca507a7' => 'Добавете запис по-горе или от сървърната част на приложението на партиди до 100.',
    'writes_531995e8' => 'запис',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'Вие сте единственият собственик. Първо прехвърлете собствеността на друг човек или изтрийте организацията.',
    'you_can_also_part1_part2_part3_53f32513' => 'Друга възможност: :part1 :part2. :part3',
    'you_can_set_this_back_to_prefer_sso_or_both__b84203a4' => 'Можете по всяко време да върнете настройката на „Предпочитане на SSO“ или „И двете са достъпни“. Прекратените сесии остават прекратени.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Губите достъпа веднага. Като собственик можете да напуснете само след като друг поеме собствеността. Първо я прехвърлете или изтрийте организацията от настройките.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Губите веднага достъп до тази организация и приложенията ѝ. Администратор може да ви покани отново.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Собственият модел за достъп на приложението: типове ресурси, отношенията за всеки тип и наследяването им. Приложението записва кортежи, които описват кой с какво е свързан, и проверява достъпа при всяка заявка.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'Политиката ви за удостоверяване продължава да важи: надеждност на паролата, проверка за изтичания, потвърждение на имейл, ограничения на заявките и проверки за ботове.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Вашият собствен API. Вие избирате поотделно кои обхвати на достъп могат да заявяват приложенията, регистрирани от организации.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'Страницата ви за вход получава връзка „Създаване на акаунт“, а приложенията могат да насочват потребителите директно към регистрация с :part1.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'Можете по всяко време да върнете настройката на „Предпочитане на SSO“ или „И двете са достъпни“. Прекратените сесии остават прекратени.',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'Ролите и разрешенията в токена са моментна снимка. Преди всяко защитено действие получете актуално решение за достъп от Cbox ID и проверете достъпа до конкретния ресурс в приложението си. Самото съдържание на токена не отразява последващо отнемане на достъп:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Вашите методи за вход и активни сесии. Ключът за достъп е най-сигурният и най-бързият вариант: устройството го отключва с пръстов отпечатък или лице и не остава парола, която да бъде открадната чрез фишинг.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Всяко действие се приема във вида, в който приложението го изпраща. Добавете схема за действие, за да се проверяват събитията му при получаване. Последователността на журнала се осигурява при записването на събитието, а не при прочитането му.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Всеки API ключ в конфигурацията или файла за средата на приложение е ключ, който не можете да смените централизирано или да отнемете бързо. Съхранен тук, той е криптиран, достъпът се дава поотделно на приложенията и може да се отмени с едно щракване.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Бутонът спира да се показва и данните за достъп се изтриват. Хората, които са влезли чрез този доставчик, запазват акаунтите си и могат да продължат да използват паролата си. За да запазите данните за достъп, изключете доставчика, вместо да го изтривате.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Обратната посока: Cbox ID изпраща хората ви към другите SaaS продукти, използвани от компанията, чрез техните SCIM крайни точки. Едно място за предоставяне и отнемане на достъп вместо отделен административен панел за всеки доставчик.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Създава организацията, нейния собственик, първия ѝ продукт и производствената среда на този продукт. Собственикът получава по имейл връзка, за да зададе собствена парола — не я избирате вместо него.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'В момента някой добавя и премахва хора тук ръчно. Свържете директорията, която компанията вече поддържа, и двете дейности ще се извършват автоматично — включително премахванията, които най-често се забравят.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Всички издадени от него токени се отменят сега и той не може да се използва за ново влизане. Приложение, което проверява токените самостоятелно, спира да ги приема при изтичането им, най-късно до края на самата сесия.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Докато мигрирате от друга система, приложението може да посочи къде се намира старото му влизане — в манифеста си, до ролите. То се показва тук за одобрение, преди да извърши каквото и да е действие.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Напишете правило за разрешаване, допълнителна проверка или блокиране според това, което знаете за потребителите. Изисквайте допълнителна проверка при влизане от държави, в които не работите, или освободете офисната мрежа от правилата за честота.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Потвърждаването на собствен домейн, например acme.com, позволява на Cbox ID да разпознава хората ви по имейл адреса и да ги изпраща направо към вашия доставчик, без да се налага да избират правилния бутон за вход.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Доставчик на идентичност, който импортира метаданни на доставчика на услуги, използва този URL адрес вместо отделно въвеждане на идентификатора на обекта и ACS URL адреса. Той работи и преди да е попълнена конфигурацията от страната на доставчика на идентичност.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Това действие не може да бъде отменено. Данните за достъп, членствата и личните данни се изтриват, а акаунтът се псевдонимизира. Ако човекът е единственият собственик на организация, първо прехвърлете собствеността.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Действате като този човек, в неговата сесия и с неговите права. Достъпът е ограничен до 30 минути и само за четене там, където конзолата може да го наложи. Всяка заявка се записва на ваше име.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Спирането е единствената промяна, която тази страница прави, и може да бъде отменено. Избирането и отварянето на среда променят само изгледа на конзолата; не променят нищо в нито една среда.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'В момента хората влизат с данни за достъп, съхранявани тук. Свържете вашия доставчик, за да използват съществуващия си фирмен акаунт и да губят достъп тук веднага щом го изключите там.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Не се издава нова тайна. От следващия опит, включително повторните опити, доставките съдържат заглавките на другата схема. Получател, който не е актуализиран, ще отхвърля всяка от тях.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Изпратете тази еднократна връзка на администратора на техния доставчик на идентичност, ако не я е получил по имейл. Работи без акаунт до изтичането си. Копирайте я сега — показва се само веднъж.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Софтуерът в тази среда, който очаква разрешение от човек. Агент, чийто ключ изисква одобрение, спира и пита човека, създал ключа. Отговорете тук или от телефона си.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Организацията обединява потребители, методи за вход и роли. Създайте една по-горе или инициализирайте средата с първата ѝ организация и администратор от екрана „Среди“.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Добавете човека в една от организациите по-долу, за да му дадете достъп в нея. Ако приложенията ви нямат собствено разделяне по организации, дайте му роля за администрация и поддръжка, валидна в цялата среда.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Роля за администрация и поддръжка се дава на собствения ви екип за цялата среда. Тя важи във всяка организация и администраторите на организациите не могат да я виждат или променят.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Заявките се появяват автоматично тук, когато приложение или агент се нуждае от одобрението ви, за да действа от ваше име. Дотогава няма какво да правите. Ако се появи заявка, която не сте започнали, откажете я.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'SMS е най-слабият втори фактор: който поеме контрола над телефонния ви номер, получава кодовете ви. Предпочитайте приложение за удостоверяване или ключ за достъп и използвайте SMS само ако тези варианти не са възможни.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Визуалната идентичност по подразбиране на средата: изгледът, логото и favicon иконата на хостваната страница за вход, както и името и подателят, които хората виждат. Всяка организация ги наследява, освен ако не зададе свои.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Подробности за организацията в целевата среда: членове, SSO, домейни, права и скорошна активност. Единственото, което тази страница променя, е състоянието на организацията.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Всички организации в тази инсталация. Отворете една, за да разгледате продуктите и средите ѝ. Спирането ѝ прекратява сесиите на членовете и спира удостоверяването във всички нейни среди.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Приложението ви изпраща тези събития с едно извикване за всяка група, като всяко събитие посочва организацията, в която е възникнало. Показват се тук и на администраторите на съответната организация при получаването им.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Достъпен е на всяка страница за вход в цялата среда. Изберете организация, за да настроите неин собствен доставчик, който замества този на средата на страницата на организацията.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code отваря браузъра за влизане тук и ви пита какво да разрешите. Няма ключ, който да пазите. Всеки MCP клиент, който влиза с OAuth, работи по същия начин с този URL адрес.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Една организация в тази инсталация: екипът, проектите и всички среди на тези проекти. Спирането ѝ прекратява сесиите на членовете и спира удостоверяването във всички тези среди.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'За цялата среда: всеки с акаунт в тази среда, от която и да е организация, може да влезе в приложението. Посочете организация, ако не искате толкова широк достъп.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Влизането с Entra ID, Okta или Google Workspace е достъпно с плана Enterprise. Свържете се с екипа, който обслужва акаунта ви, за да го активира за тази организация.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Къде сте влезли, какво може да действа от ваше име и какво се е случило с акаунта ви. Ако видите нещо непознато, прекратете съответната сесия и сменете паролата си.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Колко хора са влезли и колко често приложенията са извиквали API през последните 30 дни. Данните служат за наблюдение на натоварването и откриване на аномалии; това не е фактура.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Този потребител притежава или администрира организация и не е позволено да влизате от негово име. Достъпът до такъв акаунт би могъл да даде траен контрол над организацията на човека, който го направи.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'API ключове, с които приложенията и агентите ви се представят пред други услуги. Всяка стойност се съхранява криптирано, предоставя се само на разрешените приложения и никога не се показва отново след записване.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Приложения, които искат да действат от името на ваш потребител. Всеки потребител одобрява собствените си заявки. Откажете заявка тук само ако изглежда като злоупотреба; отказът се записва в одитния журнал.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Колко често да се извличат данни и кои собствени полета на HR системата да се копират за всеки човек, например разходен център или местоположение. Промяната на полетата прави следващото изпълнение пълно.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Връзки, дадени на IT администратора на тази организация, които все още предоставят достъп. Отмяната на връзка я спира веднага; вече настроеното чрез нея се запазва.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Заявките от агенти за действие от името на потребител се показват тук при получаването им. Всеки потребител одобрява своите; тази страница служи за отказ на заявки, които изглеждат като злоупотреба.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Когато ВСИЧКИ условия са изпълнени, Radar предприема действието на това правило и не проверява следващите. Правилата се проверяват след списъците с разрешения и за блокиране и преди вградените правила.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Одитните събития, които приложението изпраща за всички обслужвани организации, с най-новите първо. Събитията на всяка организация образуват собствена хеш верига.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Всичко, което организацията е настроила, и оставащото за изпълнение. Контролният списък следи действителното състояние: стъпката се отбелязва автоматично в момента, в който наистина е завършена.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Като администратор добавете и приложение за удостоверяване или ключ за достъп. При превземане на телефонния ви номер могат да бъдат прихванати SMS съобщенията, затова те не могат да са единственият ви втори фактор.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Изтриването на тази организация премахва всички нейни проекти и среди. За да се защитят действащите доставчици на идентичност, тази операция не е на самообслужване. Свържете се с поддръжката, за да продължите.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Потребителят веднага губи достъп до всички страници на платформата в тази инсталация, а съществуващите му сесии спират при следващата заявка. Можете да го активирате отново тук.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Потвърдените домейни насочват хората към вашия доставчик на идентичност — функция от плана Enterprise. Свържете се с екипа, който обслужва акаунта ви, за да я активира за тази организация.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Разрешението е едно действие, което ролята може да извършва, например създаване на фактури или четене на отчети. Тук можете да създавате собствени разрешения без код и после да ги обединявате в роли. Приложенията могат автоматично да регистрират своите, така че списъкът да съответства на действително прилаганите правила. Създадените от вас разрешения са ваши. Споделените от средата можете да използвате, но не и да променяте.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Правилата за пароли, заключване, задължителен втори фактор и единен вход, които важат при всяко влизане. За цялата среда се определят и наличието на ключове за достъп и връзки за вход, както и продължителността на сесията. Средата задава основата, която всички организации наследяват. Организацията може да затегне правилата за пароли и втори фактор, но не и да ги облекчи.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Действията, за които агентите в тази среда очакват разрешение от човек. Агент, чийто ключ изисква одобрение за действие, спира и пита създателя на ключа. Той може да отговори от телефона си или тук. Всеки администратор на средата може да отхвърли подозрителна заявка. По-долу са заявките от приложения да действат от името на потребителите, които всеки потребител одобрява лично.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Сесиите и токените на човека се отменят. Ключовете за достъп, вторите фактори, членствата, назначенията на роли, API токените, тайните в хранилището, устройствата и всички запазени копия на данните му се изтриват. От акаунта остава само псевдонимизиран, деактивиран запис. Приложенията, които синхронизират хора оттук, получават указание да го изтрият. Одитният журнал запазва непрозрачния идентификатор, без името или адреса.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Всичко, което сте одобрили, включително устройства или инструменти от командния ред, от които сте влезли.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Данни, които вашите системи трябва да съхраняват за тази организация. Редовете без ключ се пропускат.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'Оценяват се след вашите правила. Всяко задействано правило се записва; най-строгото определя решението.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'Доставянето се възобновява. Записите, създадени, докато е било изключено, остават в изчакване и ще бъдат изпратени със следващата партида.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'Доставянето спира незабавно и съхранените данни за удостоверяване се унищожават. Одитният журнал остава непроменен.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Всички връзки между Cbox ID и други системи на едно място: единен вход, вход със социален акаунт, синхронизация на директории и HR системи, изходящо създаване и управление на акаунти, SAML приложения, webhooks, hooks, потоци от журнали и канали за данни. От каталога се стартира настройването на всеки вид — всяка карта отваря съответната страница. Списъкът с връзки показва всички съществуващи връзки и състоянието им, първо тези с грешки.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Всички начини за вход тук — парола, ключове за достъп, връзка за вход, социален акаунт, корпоративен SSO и втори фактор — с информация дали са включени и къде се променят. Повечето се определят от средата, а SSO връзките принадлежат на всяка организация. Ако инсталацията е изключила или ограничила метод, страницата го посочва заедно със съответната настройка.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Агент е всеки софтуер, който действа в тази среда с ключ за управление: AI асистент като Claude Code или Cursor, вътрешен бот или собствената ви backend система. Дайте на всеки отделен ключ само с необходимите обхвати. Определете кои действия чакат одобрение и отменете ключа веднага щом агентът приключи или нещо изглежда съмнително.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'API е ваша услуга, която получава токени за достъп, например https://api.example.com. Регистрирайте я с обхватите, които разпознава, за да можете да ги предоставяте. Вие определяте кои обхвати могат да искат приложенията, регистрирани от организациите в средата. Токенът за API съдържа адреса му като целева аудитория, която услугата ви проверява.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Как одитната следа напуска Cbox ID: планираният експорт изпраща нови записи към SIEM или архив на всеки пет минути. Ежедневна задача за съхранение създава контролна точка, без да изтрива данни. Тук можете да изтеглите одитната история на човек за искане за достъп по ОРЗД или в конзолата на средата да проверите дали експортите работят.',
    'exactly_as_shown_part1_stays_disabled_until_it_matches_fa10ae07' => 'Въведете точно както е показано. Бутонът „:part1“ остава неактивен, докато текстът не съвпадне.',
    'my_part1_app_40bca4ad' => 'Моето приложение :part1',
    'one_long_running_process_php_artisan_queue_autoscale_st_9e4a3b67' => 'Един дълго работещ процес, php artisan queue:autoscale, стартира и спира работните процеси, които изпълняват задачите в опашката.',
    'this_will_allow_part1_to_6ac64554' => 'Приложението :part1 ще може да:',
    'totp_added_on' => 'Добавено: :date',
    'totp_rename_named' => 'Преименуване на :name',
