    'value0_not_included_in_this_organization_s_p_a6447bb1' => ':value0 Не е включено в плана на тази организация.',
    'create_one_on_platform_environments_and_its_counts_appe_2e1a2d8f' => 'Създайте среда в Платформа › Среди и нейните бройки ще се покажат тук.',
    'every_environment_on_this_install_and_how_much_of_the_e_1d09cf29' => 'Всички среди в тази инсталация и делът на всяка от тях в общия обем',
    'every_queue_this_install_sends_background_work_through_562c4113' => 'Всички опашки за фонови задачи в тази инсталация и времето за изчакване на най-старата задача във всяка от тях',
    'every_usage_counter_for_this_window_and_the_raw_metric_22633817' => 'Всички броячи за използване за този период и оригиналните ключове на съответните метрики',
    'find_an_organization_or_a_user_across_every_environment_e71f4ea0' => 'Намерете организация или потребител във всички среди, а не само в избраната в конзолата.',
    'no_claimed_domain_matches_that_try_part_of_the_domain_w_1212eb45' => 'Няма съвпадащ заявен домейн. Опитайте с част от домейна, без @.',
    'no_connections_match_that_name_try_a_different_search_t_6555c50e' => 'Няма връзки с това име. Опитайте с друга дума за търсене.',
    'no_directory_matches_that_name_try_a_different_search_t_bfc6957c' => 'Няма директория с това име. Опитайте с друга дума за търсене.',
    'no_endpoint_url_matches_that_search_try_a_different_one_45378b36' => 'Няма URL адрес на крайна точка, който да съответства на търсенето. Опитайте с друго търсене.',
    'no_entry_matches_those_filters_try_a_broader_term_or_cl_afd8d040' => 'Няма запис, който да съответства на тези филтри. Опитайте с по-обща дума или премахнете филтър.',
    'no_log_stream_matches_that_name_try_a_different_search_ac9bbc7c' => 'Няма поток от журнали с това име. Опитайте с друго търсене.',
    'no_outbound_connection_matches_that_name_try_a_differen_2fb976c3' => 'Няма изходяща връзка с това име. Опитайте с друго търсене.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Всички елементи на марката, които потребителите виждат, на една страница: лого, favicon, цветове, шрифт и заобляне на хостваната страница за вход с преглед в реално време, както и име на продукта, подател на имейли и приветствено писмо. Настройте ги веднъж за цялата среда и всички организации ги наследяват или задайте собствен облик на организация от раздел Брандиране.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Всеки проект в организацията има собствен план и лимит на среди. Те са показани тук до потреблението за месеца: организации, таксувани връзки за единен вход и влизания. Цената отчита месечните активни потребители и корпоративните връзки като SSO и SCIM. В тестовите среди няма такса за връзки.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Всички API ключове, създадени от хората в тази организация за нейните приложения: притежател, приложение, разрешени действия и последно използване. Ключът може само това, което може притежателят му, и спира да работи, когато той напусне. Отменете ключовете, които са изтекли или вече не се използват. Всеки създава собствените си ключове в Моят акаунт.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'При миграция от друга система приложение може да поиска имейлът и паролата на човек, който още не съществува в Cbox ID, да бъдат проверени в старата крайна точка за вход. Тествайте я преди одобрение. Приетият човек се създава тук и повече не се изпраща към старата система. Докато обаче тази крайна точка не работи, хората, които още не са прехвърлени, не могат да влизат.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Одитните събития, които приложението ви изпраща за всяка обслужвана организация: кой какво е направил в продукта и кога. Съхраняват се поотделно за всяка организация в хеш верига и се показват на нейните администратори. Използвайте ги, когато организация поиска одитен журнал на акаунта си. Определете схеми, за да запазите последователна структура на събитията.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Никое бъдещо временно разрешение за достъп няма да може да отвори тази тайна. Отмяната е незабавна и окончателна.',
    'no_live_agents_revoked_and_expired_keys_stay_listed_for_8dd5437a' => 'Няма активни агенти. Отменените ключове и ключовете с изтекъл срок остават в списъка за справка.',
    'no_permissions_it_identifies_its_holder_and_nothing_mor_80cf422c' => 'Без разрешения — само идентифицира притежателя',
    'nothing_changes_for_anybody_until_this_is_on_test_a_sig_9eb3389b' => 'Нищо не се променя за никого, докато това не бъде включено. Първо тествайте влизането.',
    'only_a_hash_is_stored_if_it_is_lost_revoke_it_and_creat_6e39a401' => 'Съхранява се само хеш. Ако изгубите ключа, отменете го и създайте нов.',
    'only_the_apps_listed_here_can_lease_this_secret_everyth_3afb49f2' => 'Само изброените тук приложения могат да получат временен достъп до тази тайна. Всички останали заявки се отказват.',
    'every_other_device_holding_a_session_as_you__a01280d4' => 'Сесиите ви на всички други устройства ще спрат да работят при следващата заявка. На това устройство ще останете влезли.',
    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'Тази организация все още няма членове. Никой не може да влезе в нея, докато не бъде поканен или добавен чрез автоматизирано създаване на акаунти.',
    'no_password_is_set_here_they_get_a_sign_in_link_by_emai_5e488804' => 'Тук не се задава парола. Потребителят получава връзка за вход по имейл и избира как да влиза.',
    'each_step_is_measured_from_live_state_so_the_guide_alwa_e7f5c55e' => 'Всяка стъпка се оценява според текущото състояние, така че ръководството винаги показва реалния напредък на тази организация.',
    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Копирайте ключа сега и го предайте на агента. Съхранява се само хеш, затова ключът се показва само веднъж.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Имейл домейните на организацията, всеки потвърден с DNS TXT запис. След проверката можете да включите задължително пренасочване към SSO: всички с адрес в домейна използват корпоративната SSO връзка вместо парола. Проверете всички домейни, в които хората имат адреси, преди да разчитате на единен вход.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Собственият модел за достъп на приложението: типове ресурси като документи и папки, отношения като собственик, редактор и читател и тяхното наследяване. Например читателите на папка могат да четат всеки документ в нея. Приложението записва кой как е свързан с ресурсите и при всяка заявка пита дали потребителят може да редактира документа. Схемата определя отговора.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Тази среда предоставя MCP сървър, стандартния начин AI асистентите да извикват инструменти, наред с REST API. Поставете адреса и ключ за управление в Claude Code, Cursor или друг MCP клиент. Агентът може да прави точно това, което позволяват обхватите на ключа, със същите проверки и одитен журнал като в конзолата.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Ключът позволява на скриптовете и интеграциите ви да извикват API на приложение от ваше име, без влизане. Той може само това, което можете вие в приложението: ако достъпът ви бъде ограничен, ключът също го губи. Ключът се показва само веднъж. Копирайте го при създаване и го отменете незабавно при изтичане или когато вече не се използва.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'Автоматизираното управление на акаунти спира и съпоставянията на групи се премахват. Създадените потребители остават.',
    'provisioning_stops_immediately_and_every_group_mapping_7a323b54' => 'Автоматизираното управление на акаунти спира незабавно и всички съпоставяния на групи се премахват. Това действие е необратимо.',
    'provisioning_to_the_downstream_app_stops_immediately_th_6d193c25' => 'Автоматизираното управление на акаунти в целевото приложение спира незабавно. Това действие е необратимо.',
    'provisioning_to_the_downstream_app_stops_immediately_th_948dd5a5' => 'Автоматизираното управление на акаунти в целевото приложение спира незабавно. Вече създадените там потребители остават.',
    'phone_number_removed_their_other_factors_and_recovery_c_a792580f' => 'Телефонният номер е премахнат. Останалите фактори за удостоверяване и кодовете за възстановяване на потребителя остават непроменени.',
    'people_already_connected_keep_the_scopes_they_agreed_to_f979f289' => 'Вече свързаните потребители запазват одобрените от тях обхвати, докато не се свържат отново.',
    'origins_updated_the_change_is_live_on_the_next_request_6bb5bfb0' => 'Източниците са актуализирани. Промяната влиза в сила при следващата заявка.',
    'other_systems_may_be_using_this_changing_it_changes_the_41e0f485' => 'Други системи може да използват тази стойност. Промяната ѝ променя URL адресите, които са съхранили.',
    'people_who_rely_on_this_provider_lose_their_way_in_this_10f27c15' => 'Потребителите, които разчитат на този доставчик, губят този начин за вход. Това действие е необратимо.',
    'project_suspended_its_environments_stay_live_but_no_new_be6ca1ef' => 'Проектът е спрян. Средите му остават активни, но не могат да се добавят нови, докато проектът не бъде активиран отново.',
    'role_definition_activated_existing_holders_now_use_thes_381596d2' => 'Дефиницията на ролята е активирана. Текущите притежатели вече използват тези разрешения.',
    'rule_activated_grants_that_would_break_it_are_blocked_f_fb4adf4c' => 'Правилото е активирано. Отсега нататък предоставянето на достъп, което би го нарушило, се блокира.',
    'schema_saved_events_of_this_action_are_checked_against_8215a899' => 'Схемата е запазена. Отсега нататък събитията за това действие се проверяват спрямо нея.',
    'schema_saved_every_check_is_decided_by_it_from_now_on_e54cf8c0' => 'Схемата е запазена. Отсега нататък тя определя резултата от всяка проверка.',
    'refuse_events_whose_action_has_no_schema_turn_on_once_e_c5af42c9' => 'Отказвайте събития, чието действие няма схема. Включете тази опция, когато всяко действие, изпращано от приложението ви, има схема.',
    'objects_are_written_to_prefix_yyyy_mm_dd_hh_batch_ndjso_5c6035ae' => 'Обектите се записват в prefix/yyyy/mm/dd/hh/batch.ndjson.gz, по едно събитие на ред.',
    'only_for_an_s3_compatible_store_such_as_minio_or_cloudf_266ca7ae' => 'Само за хранилище, съвместимо със S3, като MinIO или Cloudflare R2. Ако е празно, се използва крайната точка на AWS за региона.',
    'register_this_as_an_allowed_redirect_uri_at_the_provide_b537b90c' => 'Регистрирайте това при доставчика като разрешен URI за пренасочване, точно както е показано.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhooks, известията за изход към свързани приложения, актуализациите на роли, получени от тях, и имейлите в опашката се обработват във фонов режим от процеси за опашки, без потребителят да чака. Ако няма работещ процес, нищо не се изпраща, въпреки че останалата конзола изглежда нормално. На тази страница се вижда проблемът.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Преглед, при който проверявате кой има всяка роля и потвърждавате дали още се нуждае от нея. Достъпът се натрупва незабелязано: хората сменят екипи, но запазват старите разрешения. Прегледът позволява да ги премахнете. Отнеманията се прилагат при приключването му, а целият процес се записва за одитора.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Ако приложението по-късно посочи друг URL, одобрението се отменя и се изисква отново. Промяната на мястото, където се изпращат паролите, изисква ново одобрение. Делегираният вход е преходно решение: когато в старата система останат малко хора, го изключете и им изпратете връзки за нулиране на паролата.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Позволява вход със съществуващия фирмен акаунт, например Microsoft Entra ID, Okta или Google Workspace, вместо с отделна парола тук. Свържете доставчика на идентичност веднъж и потвърдете имейл домейните. Всички потребители от тези домейни ще бъдат насочвани към доставчика за вход.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Всеки човек с идентичност в тази среда, независимо от организациите, в които членува. Отворете човек, за да нулирате паролата или втория фактор, да прекратите сесиите, да деактивирате акаунта, да промените организациите и ролите или да изтриете данните окончателно при искане за упражняване на правото на изтриване.',
    'paste_the_provider_s_metadata_xml_or_its_metadata_url_a_70d6c8b8' => 'Поставете XML метаданните на доставчика или URL адреса им и полетата по-долу ще се попълнят автоматично.',
    'paste_this_into_your_identity_provider_with_the_bearer_6f366a6e' => 'Поставете това при вашия доставчик на самоличност заедно с bearer токена от директорията, която свързвате.',
    'point_your_oidc_client_at_these_discovery_exposes_every_81f0fa9a' => 'Настройте OIDC клиента си с тези адреси. Автоматичното откриване предоставя всички крайни точки.',
    'register_an_application_that_uses_this_environment_as_i_8eee8cef' => 'Регистрирайте приложение, което използва тази среда като доставчик на самоличност по SAML.',
    'register_one_to_let_an_application_sign_its_users_in_wi_e20e6b01' => 'Регистрирайте приложение, за да могат потребителите му да влизат с акаунтите, които вече имат в тази среда.',
    'only_the_apps_listed_here_get_a_token_everything_else_i_3d600e70' => 'Само изброените тук приложения получават токен. Всички останали заявки се отказват.',
    'no_entitlements_set_for_this_organization_it_runs_on_th_76313cb5' => 'За тази организация няма зададени права за използване. Прилагат се настройките по подразбиране на инсталацията.',
    'organizations_in_the_targeted_environment_as_the_manage_2f2361fb' => 'Организациите в целевата среда, представени като дърво за управление.',
    'owned_by_this_environment_rather_than_by_an_organizatio_60be3a32' => 'Принадлежи на тази среда, а не на организация',
    'platform_operators_administer_environments_across_the_w_e0a9f173' => 'Операторите на платформата управляват средите в цялата инсталация.',
    'platform_wide_usage_across_every_environment_not_only_t_0e12a08a' => 'Използването на цялата платформа във всички среди, а не само в избраната в конзолата.',
    'how_organization_owners_and_operators_sign_in_to_cbox_i_444d5c8b' => 'Начинът, по който собствениците и операторите на организации влизат в Cbox ID, се задава в конзолата на средата на платформата.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Тези точки за разширение се изпълняват по време на операцията, а не след нея, и отговорът им променя резултата: крайната ви точка може да добави данни към токен или да откаже входа. Те участват пряко в изпълнението на операцията — бавна или неработеща крайна точка се усеща от човека, който се опитва да влезе.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Доставчикът на идентичност сам създава, актуализира и деактивира хора тук чрез стандарта SCIM. Назначаване или напускане, отбелязано в системата за човешки ресурси, достига приложенията за секунди, без заявки за поддръжка и забравени акаунти — особено важно при напускане.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Броят на организациите, потребителите, връзките за единен вход, приложенията и синхронизациите на потребители в тази среда, всяко с връзка към собствената си страница. Преките пътища по-долу започват най-честите действия: създаване на организация, потребител, връзка за единен вход или приложение.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Ролята е отговорност, която приложенията ви разбират, например „Редактор“ или „Служител по поддръжката“. Тук определяте кой има всяка роля, а всяко приложение решава какво позволява тя. Ролите следват човека във всички свързани приложения, така че предоставяте и отнемате достъп на едно място.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Копира всеки запис от журнала за одит в инструментите на екипа по сигурността, като SIEM, още при записването му. Настройте местоназначение, за да започват разследванията във вече използваните инструменти, без заявка за експорт. Доставката е поне веднъж, затова са възможни дублирани записи.',
    'an_organization_appears_here_the_moment_somebody_signs__d46ff7af' => 'Организация се появява тук веднага щом някой се регистрира. Можете и сами да създадете такава чрез Нова организация по-горе.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Добавете домейна на имейл адресите на хората в тази организация, публикувайте TXT записа и потвърдете домейна.',
    'prove_ownership_of_an_email_domain_to_route_your_team_t_bc84ec01' => 'Докажете собствеността върху имейл домейн, за да насочвате екипа си автоматично към SSO.',
    'prove_the_organization_owns_a_domain_then_route_everyon_3c9f7db4' => 'Докажете, че организацията притежава домейн, и насочете всички негови потребители към входа на организацията.',
