    'secret_rotated_and_the_previous_one_has_stopped_working_14aacb17' => 'Тайната е сменена и предишната вече не работи. Копирайте новата сега — няма да се покаже отново.',
    'revoking_is_immediate_and_permanent_no_future_lease_can_27e17e18' => 'Отмяната е незабавна и окончателна. Никое бъдещо временно разрешение за достъп няма да може да отвори тази тайна.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Схемите за метаданни са подмножество на JSON Schema: обект със свойства от тип низ, число, цяло число, булева стойност или null, с изброявания и ограничения за дължина, диапазон, шаблон и формат. Записването на промяна създава нова версия; вече записаните събития запазват версията, по която са проверени.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Всяка връзка позволява на хората да свържат собствен акаунт в услуга като GitHub, Google или Slack. Токените се съхраняват шифровано и се обновяват тук. Упълномощените приложения искат валиден токен всеки път, когато извикват услугата от името на човека, без сами да съхраняват токени.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Роля за администриране и поддръжка се предоставя на собствени служители, например от екипите за поддръжка или експлоатация, за цялата среда. Тя важи във всяка организация, а администраторите на организациите не могат да я виждат, предоставят или премахват. Собствена роля на приложение, предоставена по този начин, важи само за него.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Средата е напълно изолирана услуга за идентичност със собствени потребители, ключове, вход и издател. Тук са изброени всички среди на тази инсталация с организацията, която ги притежава. Създайте среда, изберете я в конзолата и добавете първата организация и администратор.',
