    'the_hr_system_s_own_field_names_to_copy_onto_each_perso_2c74edb8' => 'Имената на полетата от HR системата, които да се копират за всеки потребител, по едно на ред — например разходен център или местоположение.',
    'the_identifier_the_application_calls_itself_in_its_auth_afe05ddf' => 'Идентификаторът, с който приложението се представя в своите AuthnRequests.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Телефонът с инсталирано приложение за удостоверяване позволява да отговаряте на заявки за одобрение и ви уведомява, когато някой влиза в акаунта ви. Регистрирайте го веднъж чрез сканиране на кода. Ако го изгубите, незабавно го премахнете оттук, за да не може да одобрява нищо повече.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Организацията е мястото на една регистрирана компания в тази инсталация и съдържа проектите, средите и екипа ѝ. Отворете я, за да разгледате продуктите и средите, или я спрете: това прекратява сесиите на членовете и спира входа във всички нейни среди.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Когато приложение или AI агент се нуждае от разрешение да действа от ваше име, невинаги може да го поиска на екрана пред вас — затова го иска тук. Одобрявайте само заявки, които сами сте започнали, и проверявайте дали кодът съвпада с този на устройството, изпратило заявката.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Проектът е един от продуктите ви със собствен план, вход и среди, например продукционна и предпроизводствена. Отворете среда оттук, за да я администрирате. Създайте нов проект, когато пускате продукт, който трябва да се фактурира и управлява самостоятелно.',
    'send_this_endpoint_every_organization_s_events_in_this_ea696387' => 'Изпращайте към тази крайна точка събитията на всички организации в тази среда, а не само на една.',
