    'the_hook_stops_being_called_and_its_signing_secret_is_d_ad833a77' => 'Hook-ът вече няма да се извиква и тайната му за подписване се унищожава. Това действие е необратимо.',
    'the_bucket_in_the_path_rather_than_the_host_name_a_cust_070b78d0' => 'Името на S3 контейнера е в пътя, а не в името на хоста. Персонализираната крайна точка вече използва този формат.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Всяко приложение, което вписва хора чрез Cbox ID или извиква неговия API, се регистрира тук и получава собствени данни за удостоверяване. Създавайте отделна регистрация за всяко приложение и среда. Никога не споделяйте тези данни, за да можете да ги отнемете за едно приложение, без да спирате останалите.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Търси организация по име или идентификатор, или потребител по име или имейл, във всички среди на тази инсталация, а не само в избраната в конзолата. Използвайте, когато някой поиска помощ и не знаете в коя среда се намира.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Вижте приложение точно както го вижда негов потребител: влизате от негово име с посочена причина за най-много един час. Приложението научава кой всъщност го използва и не получава възможност да поддържа сесията. Журналът за одит на организацията записва кой го е направил и защо.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'Проектът е един IdP продукт, притежаван от тази организация, към който принадлежат средите. Докато организацията не създаде проект от собствената си конзола, тук няма среда за избор или отваряне. Този екран не позволява създаване на проект от името на организацията.',
