    'the_hosted_sign_in_s_look_logo_and_favicon_and_the_name_39304e21' => 'Изгледът, логото и favicon иконата на хостваната страница за вход, както и името и подателят, които виждат потребителите.',
    'sent_when_someone_s_account_is_created_leave_it_empty_f_c7c58d7f' => 'Изпраща се при създаване на акаунт. Оставете празно за стойността по подразбиране.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Само за доставчик, който не публикува ключовете си за подписване (jwks_uri) в документа за откриване. Иначе ключовете се четат оттам, включително при ротация. Въведете публичен ключ PEM. Съхранява се шифровано и не се показва отново; оставете празно, за да запазите текущия.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Някои двойки роли никога не трябва да принадлежат на един човек: който нарежда плащане, не бива и да го одобрява. Посочете тези двойки тук. Cbox ID блокира нови предоставяния, които нарушават правилото, и показва кой вече има конфликтна двойка роли.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'API ключове и токени, нужни на приложенията и агентите ви за други услуги, съхранявани шифровано тук вместо в конфигурацията на всяко приложение. Въвеждате тайната стойност веднъж и давате на конкретни приложения право да я използват. Тя не се показва отново; ако я изгубите, заменете я.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Предоставя крайните точки за идентичност на среда на ваш домейн, например login.example.com, вместо на нашия. Доказвате собствеността с DNS TXT запис. Настройте го, когато хората трябва да виждат само вашия адрес при вход.',
