    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Всяка организация е компания или екип, използващ продукта ви, със собствени членове, роли, домейни и единен вход. Създайте по една за всяка регистрирана компания. Отворете я за управление на членове, покани и потвърдени домейни или за спиране.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID изпраща подписано съобщение до крайната ви точка след събитие, например присъединяване на член или промяна на роля, за да реагират системите ви без периодични заявки. Неуспешната доставка се повтаря. Събитието вече е станало: крайната точка се уведомява, но не решава резултата.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Схемата определя структурата на събитията за действие: какви типове целеви обекти посочват и какво съдържат метаданните им. Събитията на действие със схема се проверяват при получаване. Без схема се приемат както са изпратени, освен ако е включен строг режим.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Всички администратори на тази организация, вградената роля на всеки — Собственик, Администратор, Разработчик, Член или Наблюдател — и достъпните им среди. Канете хора по имейл и давайте на всеки само средите, необходими за работата му.',
