    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Операторите на платформата администрират всички организации и среди на тази инсталация над нивото на всяка отделна от тях. Добавяйте оператор само за човек, който поддържа самата инсталация, и го спирайте веднага щом това престане да е негова задача.',
