    'every_environment_on_this_install_and_who_owns_it_creat_78b48199' => 'Всички среди на тази инсталация и техните собственици. Създайте среда, изберете я в конзолата и добавете първия администратор.',
    'every_member_is_signed_out_of_it_and_refused_at_every_d_67c21f22' => 'Всички членове излизат от сесиите си и достъпът им се отказва по всички начини, а приложенията спират да приемат влизанията им. Това не може да се отмени от конзолата.',
    'every_organization_in_the_target_environment_the_manage_9b4126ae' => 'Всички организации в целевата среда: дървото за управление на препродавачите, управляваните от тях организации и подразделенията.',
    'every_organization_s_people_are_pushed_to_this_one_targ_27734b94' => 'Хората от всички организации се изпращат към това единствено местоназначение. За разлика от избора на организация по-горе, тази връзка обхваща цялата среда.',
    'from_the_next_attempt_nothing_is_refused_or_challenged_0dcf7713' => 'От следващия опит нищо няма да бъде отказвано или подлагано на допълнителна проверка — включително масовото изпробване на откраднати данни за вход. Решенията продължават да се записват.',
    'how_your_organization_s_own_team_signs_in_to_cbox_id_no_11ea0db7' => 'Как собственият екип на работното ви пространство влиза в Cbox ID — не в приложенията ви: техният вход се настройва в конзолата на всяка среда.',
    'it_disappears_from_every_list_and_its_people_are_refuse_49a9035c' => 'Организацията изчезва от всички списъци и хората ѝ губят достъп навсякъде, точно както при спиране. Записите се запазват.',
    'left_empty_a_signing_key_is_generated_for_you_and_shown_7cc3e0ba' => 'Ако оставите празно, се генерира ключ за подписване и се показва само веднъж. Съхранява се шифровано и не може да бъде извлечен отново.',
    'let_your_identity_provider_create_update_and_deactivate_1208087e' => 'Позволете на доставчика на идентичност сам да създава, актуализира и деактивира хора тук и да съпоставя групите си с вашите роли.',
    'let_your_provider_create_and_deactivate_people_here_on_7db65233' => 'Позволете на доставчика си автоматично да създава и деактивира потребителски акаунти тук, така че напускащите служители да губят достъп навсякъде без заявка до поддръжката.',
    'light_mode_muted_text_on_the_background_is_ratio_1_it_n_7f4cfb27' => 'Светъл режим: приглушеният текст върху фона има контраст :ratio:1 — необходими са 3:1.',
    'light_mode_text_on_the_background_is_ratio_1_it_needs_4_22bc83f1' => 'Светъл режим: текстът върху фона има контраст :ratio:1 — за четливост са необходими 4.5:1.',
    'many_different_addresses_tried_from_one_ip_address_with_68db7387' => 'Опити с много различни имейл адреси от един IP адрес в рамките на 10 минути — изпробване на списък с изтекли данни за вход.',
