    'none_for_the_environment_yet_add_google_github_microsof_25c55363' => 'Все още няма за тази среда. Добавете Google, GitHub, Microsoft, Apple и други със собствените си OAuth данни и всяка организация ще ги предлага.',
    'only_a_hash_is_stored_so_it_will_not_be_shown_again_pas_901ca5cd' => 'Съхранява се само хеш, затова токенът няма да се покаже отново. Поставете го при доставчика на идентичност до крайната точка по-долу.',
    'only_the_encrypted_form_is_stored_so_it_cannot_be_retri_8466f568' => 'Съхранява се само шифрованата форма, така че стойността не може да се извлече отново. SIEM я използва за проверка на подписа на всяка доставка.',
    'passwords_emailed_sign_in_links_passkeys_and_social_but_6330b064' => 'Паролите, връзките за вход по имейл, ключовете за достъп и бутоните за социален вход спират да работят незабавно за всички хора в тази организация.',
    'paste_the_full_service_account_json_key_it_m_9ffc8f83' => 'Поставете целия JSON ключ на служебния акаунт — той трябва да съдържа client_email и private_key.',
    'pick_your_framework_and_get_an_app_with_a_localhost_red_70977d3d' => 'Изберете програмна рамка и получете приложение с пренасочване към localhost, блок за .env и команда за инсталиране — за около минута.',
    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Всяка страница, която отворите оттук нататък — организации, използване и детайли на организация — чете тази среда вместо текущата. Нищо не се променя в нито една от тях.',
    'everyone_in_this_organization_is_refused_at_every_door_40e035a5' => 'Всички хора в тази организация губят достъп незабавно по всички начини и организацията изчезва от списъците. Това не може да се отмени от конзолата.',
    'everything_on_this_page_is_also_a_rest_endpoint_an_mcp_28d51f03' => 'Всичко на тази страница е достъпно и като REST крайна точка, MCP инструмент и CLI команда, със същите правила и одитна следа.',
    'give_it_a_name_you_will_recognise_later_like_3cdadec6' => 'Дайте име, което ще разпознаете по-късно, например устройството или мениджъра на пароли, където се съхранява. Можете да го промените по всяко време.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Предоставете роля на хората, които поддържат или управляват приложенията ви. Собствената роля на приложение влиза само в неговите токени; роля за всички приложения влиза в токените на всяко от тях.',
    'groups_appear_here_after_the_first_sync_that_includes_t_d8006c0f' => 'Групите се появяват тук след първата синхронизация, която ги включва. Ако доставчикът филтрира изпращаните групи, списъкът отразява този филтър.',
    'recognise_your_devices_by_their_browser_ip_address_and_eb8587ae' => 'Разпознавайте устройствата по браузъра, IP адреса и дейността им. Държавата е приблизителна и се определя по записания IP адрес.',
    'removes_every_connection_through_it_tokens_are_revoked_eec0a79e' => 'Премахва всички връзки през него. Токените се оттеглят тук, не при доставчика. Ако това има значение, първо прекъснете връзките на потребителските акаунти.',
