    'its_people_are_refused_at_every_door_sign_in_the_device_5c2c7648' => 'Хората губят достъп по всички начини — вход, поток за устройства и екран за съгласие — до повторно активиране. Нищо не се изтрива.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Ключове, създадени от хората в тази организация за приложенията ѝ, с правата на всеки ключ. Всеки създава собствени; отнемайте изтекли или неизползвани ключове.',
    'keys_your_own_scripts_and_integrations_use_to_call_an_a_db6b0585' => 'Ключове, с които вашите скриптове и интеграции извикват API на приложение от ваше име. Ключът може да прави само това, което е позволено на вас в приложението.',
    'nobody_is_on_this_organization_it_has_no_owner_so_nobod_0a51d66d' => 'В тази организация няма никого, дори собственик, така че никой не може да влезе, за да я администрира. Това е грешка при първоначалното създаване, която трябва да се провери, а не просто празен списък.',
    'send_their_it_administrator_an_admin_portal_link_for_sa_59852a2e' => 'Изпратете на IT администратора връзка към Административния портал за подновяване на SAML сертификата или подгответе новия сертификат чрез API.',
    'session_ceiling_with_idle' => 'Инсталацията допуска най-много :idle без активност и :absolute общо (CBOX_ID_SESSION_IDLE_MINUTES, CBOX_ID_SESSION_TTL_MINUTES).',
    'session_with_idle' => 'Сесията приключва след :idle без активност или най-късно след :absolute.',
    'showing_this_environment_s_own_secrets_an_organization_d072355c' => 'Показват се собствените тайни стойности на тази среда. Тези на организацията са отделени на нейната страница. Изберете я чрез филтъра Организация.',
    'social_providers_owned' => ':providers — собствени конфигурации на организацията :organization: :count; останалите идват от средата.',
