    'that_favicon_cannot_be_used_keep_it_under_pixels_pixels_43e8b882' => 'Тази икона на сайта не може да се използва. Най-дългата ѝ страна трябва да е под :pixels пиксела.',
    'that_logo_cannot_be_used_keep_it_under_pixels_pixels_on_4e195f5d' => 'Това лого не може да се използва. Най-дългата му страна трябва да е под :pixels пиксела.',
    'the_account_s_last_successful_sign_in_was_too_far_away_e6d46632' => 'Последният успешен вход в акаунта е бил твърде далеч и твърде скоро, за да е възможно пътуване оттам. Изисква данни за IP адреси.',
    'the_address_belongs_to_a_hosting_provider_or_data_centr_213f7032' => 'Адресът принадлежи на хостинг доставчик или център за данни, откъдето хората рядко влизат. Изисква услуга за IP данни, която отчита това.',
    'the_admin_console_s_own_palette_as_hex_0a2540_or_oklch_71ec4917' => 'Собствената палитра на административната конзола в шестнадесетичен формат (#0a2540) или oklch(…). Страницата за вход използва цветовете на темата по-горе.',
    'the_current_signing_secret_stops_verifying_immediately_54edeb63' => 'Текущата тайна за подписване спира да проверява подписи незабавно и не може да се възстанови. Приемникът отхвърля всяка доставка, докато не бъде обновен.',
    'the_risk_score_reached_its_reject_threshold_ip_reputati_e04e768d' => 'Оценката на риска достигна прага за отказ (репутация на IP, honeypot, user agent, MX и останалите оценявани сигнали).',
    'the_secret_signs_every_delivery_s_hmac_it_is_stored_sea_830c30dd' => 'Тайната стойност подписва всяка доставка чрез HMAC. Съхранява се шифровано и не може да се извлече отново. Ротацията издава нова стойност, показвана само веднъж.',
