    'offer_part1_on_this_page_again_924a212a' => 'Предлагане на :part1 отново на тази страница',
    'nothing_is_always_refused_and_nothing_skips_the_rules_d_6699d9d9' => 'Никой адрес не е винаги блокиран и никой не заобикаля правилата. Блокирайте диапазон адреси, от който сте видели атаки, или позволете на офисната мрежа да заобикаля правилата за честота.',
    'one_marked_event_siem_stream_test_sent_now_with_this_st_c0cf0c4a' => 'Едно обозначено събитие (siem.stream.test), изпратено сега с настройките и данните за удостоверяване на потока, без опашка и повторения. Успехът премахва и състоянието „Необходимо действие“.',
    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Само активните членове на избраната организация могат да влизат в това приложение. Всички останали се отхвърлят и отказът се записва в журнала за одит.',
    'passkeys_are_turned_off_here_so_you_cannot_a_9b3b4401' => 'Ключовете за достъп са изключени тук, затова не можете да добавите нов или да влезете с такъв. Съществуващите са изброени по-долу и могат да се премахват.',
    'people_who_sign_in_through_this_provider_stop_being_abl_a0fd1fd9' => 'Хората, които влизат чрез този доставчик, губят тази възможност. Всеки с парола тук още може да влезе, освен ако се изисква единен вход.',
    'point_cbox_id_at_the_identity_provider_your_company_alr_f4f844a5' => 'Свържете Cbox ID с доставчика на идентичност, който компанията вече използва. Настройката започва като чернова; нищо не се променя до активиране.',
    'the_token_your_identity_provider_currently_holds_stops_5458b580' => 'Токенът, който доставчикът на идентичност използва сега, спира да работи веднага. Предоставянето на акаунти се проваля, докато не поставите новия токен там.',
    'this_connection_belongs_to_the_environment_not_to_one_o_5e9a5366' => 'Тази връзка принадлежи на средата, не на една организация. Задайте задължителното използване в Политиката за удостоверяване.',
    'this_connection_can_t_be_changed_while_the_organization_d78c4f4e' => 'Тази връзка не може да се променя, докато организацията няма план Enterprise. Свържете се с екипа, който обслужва акаунта ви, за активиране.',
    'this_connection_s_settings_could_not_be_read_so_nothing_0ab248ca' => 'Настройките на тази връзка не можаха да бъдат прочетени, затова нищо не е променено. Първо въведете отново настройките на доставчика на идентичност.',
    'this_endpoint_belongs_to_the_environment_and_receives_e_f1dc8df9' => 'Тази крайна точка принадлежи на средата и получава събитията на всички организации, включително вашата. Управлява я операторът.',
    'this_organization_s_brand_it_overrides_the_environment_ffdddbcc' => 'Визуалната идентичност на тази организация заменя настройката по подразбиране на средата. Промените се виждат веднага в прегледа и важат за хостваната страница за вход.',
    'this_provider_s_discovery_document_publishes_no_signing_07a38178' => 'Документът за откриване на този доставчик не публикува ключове за подписване (jwks_uri). Поставете ключа му за подписване на ID токени (публичен ключ PEM).',
    'verify_the_domain_before_turning_capture_on_until_then_4ff9f310' => 'Потвърдете домейна, преди да включите задължителното насочване към SSO. Дотогава организацията не е доказала, че притежава тези адреси.',
    'verify_the_signature_on_every_call_and_answer_within_th_5219ed81' => 'Проверявайте подписа на всяко извикване и отговаряйте в рамките на времевия лимит — това се изпълнява, докато някой чака на екрана за вход.',
    'webhook_id_webhook_timestamp_and_webhook_signature_with_73e511b0' => 'webhook-id, webhook-timestamp и webhook-signature с тайна стойност whsec_, проверими с всяка библиотека Standard Webhooks.',
    'social_provider_enabled_environment' => ':provider вече е наличен на всички страници за вход в тази среда.',
