    'they_lose_this_role_in_every_organization_at_once_apps_2750f7e3' => 'Човекът губи тази роля едновременно във всички организации. Текущите проверки за права отразяват промяната при следващото защитено действие; данните в съществуващите токени отразяват състоянието при издаване. Никой не излиза от сесия.',
    'they_lose_this_role_in_every_organization_at_once_apps_39477fda' => 'Човекът губи тази роля едновременно във всички организации. Текущите проверки за права отразяват промяната при следващото защитено действие; данните в съществуващите токени отразяват състоянието при издаване. Никой не излиза от сесия.',
    'whether_the_background_work_of_this_install_webhooks_si_0647da12' => 'Проверете дали фоновите задачи на тази инсталация — webhook-и, известия за изход до свързани приложения и имейли в опашката — действително се изпращат.',
    'your_endpoints_get_a_signed_message_after_something_hap_04723db4' => 'Крайните ви точки получават подписано съобщение след събитие, за да реагират системите ви без постоянни заявки.',
    'your_organization_s_name_domains_and_defaults_changes_h_8e3220c0' => 'Името, домейните и настройките по подразбиране на организацията. Промените важат за всички, които влизат чрез нея.',
    'your_own_credentials_with_each_provider_offered_on_ever_82ce1e08' => 'Вашите собствени данни за удостоверяване при всеки доставчик, предлагани на всяка страница за вход в тази среда. Всички организации ги наследяват.',
    'your_own_credentials_with_each_provider_offered_to_ever_d1715d1a' => 'Вашите собствени данни за удостоверяване при всеки доставчик, достъпни за всички в тази среда. Всяка организация ги наследява.',
    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'Приемникът пази същата тайна стойност и я използва точно както е записана, включително префикса whsec_, като HMAC ключ за X-Cbox-Signature.',
