    'prove_which_email_domains_your_organization_owns_a_veri_a1717fad' => 'Докажете кои имейл домейни принадлежат на организацията. Потвърден домейн може да насочва всички хора с адрес в него директно към корпоративната ви SSO връзка.',
    'push_your_people_into_the_apps_that_need_their_own_copy_249f03c2' => 'Изпращайте данните за хората към приложенията, които се нуждаят от собствено копие. SCIM крайна точка получава всяко присъединяване, промяна и напускане при възникването му.',
    'send_this_single_use_link_to_whoever_configures_your_id_e8056999' => 'Изпратете тази еднократна връзка на човека, който настройва доставчика на идентичност. Изтича скоро и работи без акаунт. Копирайте я сега: показва се само веднъж.',
