    'signed_in_to_an_app_as_one_of_this_organization_s_peopl_d9c070c7' => 'Активни сесии в приложения от името на хора от тази организация. Всяка е записана и в журнала за одит на организацията с причината.',
    'splunk_elastic_graylog_cef_and_generic_json_are_http_co_8d405816' => 'Splunk, Elastic, Graylog, CEF и Generic JSON са HTTP колектори, за които задавате URL. Datadog, Amazon S3 и Google Cloud Storage имат собствени настройки.',
