    'the_environment_default_inherited_by_every_organization_19ddab20' => 'Визуалната идентичност по подразбиране на средата, наследявана от организациите без собствена. Тази на организацията е на нейната страница в раздел Визуална идентичност.',
    'the_site_your_account_lives_on_the_domain_of_the_datado_7f128cbf' => 'Сайтът, в който се намира акаунтът ви: домейнът на Datadog URL, на който влизате. API ключът работи само в собствения си сайт.',
    'a_management_key_reads_and_writes_this_envir_aba5f345' => 'Ключът за управление чете и записва организациите и хората в тази среда чрез API, а стойността му се показва веднъж.',
