    'signing_in_to_an_app_as_this_person_lets_you_11b85bdb' => 'Влизането в приложение като този човек ви позволява да действате от негово име там.',
    'you_hold_no_permissions_in_part1_so_a_key_would_identif_2c680207' => 'Нямате разрешения в :part1, така че ключът само би ви идентифицирал, без да позволява нищо друго.',
