    'who_may_do_what_to_which_record_your_app_wri_ca6c6d61' => 'Кой какво може да прави с кой запис. Приложението ви записва връзките и иска проверка при всяка заявка.',
    'organization_created_but_the_owner_could_not_21800822' => 'Организацията е създадена, но не успяхме да изпратим връзка на собственика. Помолете го да използва „Забравена парола“.',
    'you_re_signed_in_you_don_t_belong_to_an_orga_67d0efb9' => 'Влезли сте. Все още не принадлежите към организация тук — акаунтът и настройките ви за сигурност са изцяло ваши.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Нужни са данни за удостоверяване от ваш собствен акаунт при доставчика, обикновено клиентски ID и тайна стойност. Apple вместо това издава ключ за подписване.',
    'you_stop_being_able_to_sign_in_with_it_if_it_66b928b9' => 'Повече няма да можете да влизате с този метод. Ако е единственият ви, промяната се отказва. Първо задайте парола или добавете ключ за достъп.',
    'you_will_no_longer_be_able_to_sign_in_with_a_a575bedf' => 'Повече няма да можете да влизате с код по SMS. Приложението за удостоверяване, ключовете за достъп и кодовете за възстановяване не се променят.',
