    '_not_yet_confirmed_4bae5cf3' => ' (все още не е потвърдено)',
    '_optional_edbfc3dc' => ' (незадължително)',
    'already_exists_here_4acf85c5' => 'вече има акаунт тук',
    'down_908aec45' => 'недостъпна',
    'impersonation_09d36284' => 'достъп от името на потребител',
    'including_yours_1124fe26' => 'включително вашата',
    'not_enrolled_4f827cce' => 'не е настроено',
    'not_yet_in_cbox_id_e5419fd1' => 'все още няма акаунт в Cbox ID',
    'see_your_apps_83cc472a' => 'вижте приложенията си',
    'the_full_quickstart_dd59dd4d' => 'пълното ръководство за бърз старт',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Ключът за управление действа само в собствената си среда. Експортирайте описанието на това приложение (GET /apps/{id}/blueprint) и го регистрирайте с ключа на другата среда (POST /apps с `blueprint`).',
    'add_the_domain_and_publish_the_txt_record_it_shows_or_s_ddb14174' => 'Добавете домейна и публикувайте показания TXT запис — или изпратете на ИТ администратора на организацията връзка към административния портал, за да го направи.',
    'asked_before_every_rule_a_deny_entry_blocks_an_allow_en_e80b3f61' => 'Проверява се преди всяко правило. Запис за отказ блокира; запис за разрешаване пропуска всички правила, включително вградените. Ако и двата съвпаднат за един опит, отказът има предимство.',
    'attach_this_to_the_iam_user_whose_access_key_the_stream_7659ba28' => 'Прикачете това към IAM потребителя, чийто ключ за достъп използва потокът: може да записва обекти под префикса и нищо друго — без четене, изброяване или изтриване.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Изберете SCIM, ако доставчикът ви изпраща данни към нас, Google Workspace или Entra, ако трябва да ги изтегляме, или HR системата си — Workday, BambooHR, Rippling, HiBob или Personio — за да се добавят хората на началната им дата.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'От следващия опит блокиранията отказват вход и регистрация в тази среда, а допълнителните проверки изискват потвърждение. Ако правило е неправилно, реални хора ще бъдат блокирани.',
    'give_it_the_endpoint_or_bucket_and_the_credential_it_ex_4cf81bb7' => 'Задайте крайната точка или хранилището и необходимите данни за достъп. За HTTP приемник оставете тайната празна, за да се генерира HMAC ключ.',
    'let_an_organization_sign_in_with_okta_entra_id_or_googl_cf114dfb' => 'Позволете на организация да влиза с Okta, Entra ID или Google Workspace — или изпратете на администратора ѝ връзка към административния портал, за да го настрои сам.',
    'selected_permissions_count' => 'Избрани разрешения: :count',
    'sso_required_organization' => 'Корпоративното SSO е задължително за организацията :organization. Всички други начини за вход са блокирани, докато това изискване не бъде променено в раздел „:policy“.',
    'sso_required_environment' => 'Корпоративното SSO е задължително за тази среда. Всички други начини за вход са блокирани, докато това изискване не бъде променено в раздел „:policy“.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'За потребител, който :part1, заявката за вход никога не се изпраща към старата система. Важи паролата му в Cbox ID, а старата система не участва в удостоверяването.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Ако тази крайна точка е :part1, потребителите, които не са прехвърлени, не могат да влязат. Вече прехвърлените не са засегнати.',
    'every_session_in_this_organization_ends_part1_part2_b33262fc' => 'Всички сесии в тази организация се прекратяват — :part1 :part2.',
    'the_same_code_step_by_step_with_sign_out_part1_part2_4d2f071e' => 'Същият код стъпка по стъпка, включително излизане: :part1 :part2.',
    'the_newest_entries_on_part1_s_trail_dac97d7d' => 'Най-новите записи в одитния журнал на организацията :part1.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 отказва вход, ако стойността не съвпада точно. Тя е запазена за тази настройка, така че можете да я поставите в :part2 сега и да запишете тук след това.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 — сесиите, ключовете за достъп, вторите фактори, профилите при доставчици на идентичност, данните от директории, издадените токени, зададените роли и одитната история се запазват. Човекът може да бъде активиран отново.',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => 'Препоръчителни стъпки: :part1, приблизително в този ред. Всяка се отбелязва автоматично, когато действително е завършена; не е нужно ръчно маркиране.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Тези методи не служат за вход в тази конзола. Администраторите влизат чрез Cbox ID на :part2 с неговите методи за вход.',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Ключ за управление за един агент. Той може да прави само позволеното от обхватите му, а избраните от вас действия чакат одобрение на телефона или тук: :part1.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => ':part1 е доставчикът на идентичност на един продукт, фактуриран по собствен план. Съдържа изолирани :part2 :part3 — продукционни и тестови — със собствени потребители, ключове и вход.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'Ключът за организация дава достъп до самата организация — проекти, среди, екип и ключове — не вътре в среда. Създайте го на най-горното ниво на платформата в :part1 :part2 :part3.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Приложения, които се доверяват на тази среда като SAML доставчик на идентичност. За вход със съществуващ акаунт при друга услуга използвайте :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Одобренията обхващат действията на API за управление. Тези обхвати се обслужват от крайни точки, които още не са действия, затова се изпълняват без искане за одобрение: :part1 :part2.',
    'link_an_app_with_the_same_owner_as_the_api_tokens_for_t_0a546071' => 'Свържете приложение със същия собственик като API. Токените за този API съдържат ролите и разрешенията на свързаното приложение, затова то трябва да е собствено приложение на собственика.',
    'not_configured_radar_can_still_block_but_cannot_ask_a_p_0a163809' => 'Не е настроено — Radar все още може да блокира, но не може да поиска доказателство, че потребителят е човек. При отбелязана регистрация вместо това се потвърждава имейл адресът.',
    'pick_where_the_trail_goes_splunk_elastic_graylog_cef_or_e69f3c8f' => 'Изберете къде да се изпраща одитният журнал — Splunk, Elastic, Graylog, CEF или друг JSON приемник, Datadog, или собствено хранилище в Amazon S3 или Google Cloud Storage.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Добавя ключовете на флаговете за функции, включени за човека в организацията, в която е влязъл, в токена за достъп, ID токена и UserInfo като твърдение `feature_flags`.',
    'puts_everything_userinfo_answers_for_the_app_s_scopes_e_db47369d' => 'Добавя в ID токена всичко, което UserInfo връща за обхватите на приложението (имейл, име, роли, разрешения, организации), за да може приложението да пропусне заявката към UserInfo при вход. Само за приложение, което при изход изпраща `id_token_hint` с POST или изобщо не го изпраща: токен в URL адрес се записва в журналите за достъп.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Поставя РОЛИТЕ на човека в ID токена под името `groups` — това търсят Kubernetes, Grafana, Vault и повечето по-стари SaaS приложения. В тази конзола няма обект „група“: създайте роля с името, което приложението очаква, и тя ще се появи тук.',
    'register_an_app_so_your_people_can_sign_in_to_it_with_t_9fcc62a6' => 'Регистрирайте приложение, за да могат хората ви да влизат в него с акаунта, който имат тук. Това е стъпката, която превръща Cbox ID в нещо, което използват.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Тази икона на сайта не може да се използва. Изпратете самото изображение като base64 data: URI (data:image/png;base64,…). Отдалечени URL адреси на изображения не се приемат: изображението на страницата за вход се зарежда от всеки посетител и външен адрес би разкрил на хоста му кои са посетителите.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Това лого не може да се използва. Изпратете самото изображение като base64 data: URI (data:image/png;base64,…). Отдалечени URL адреси на изображения не се приемат: изображението на страницата за вход се зарежда от всеки посетител и външен адрес би разкрил на хоста му кои са посетителите.',
    'the_address_is_a_tor_exit_node_a_vpn_or_an_open_proxy_t_f7fc0d8a' => 'Адресът е изходен възел на Tor, VPN или отворен прокси. Tor се разпознава от локалния списък с изходни възли; за VPN и прокси е нужна услуга за IP данни, която ги отчита.',
    'the_button_disappears_from_every_sign_in_page_in_this_e_c817a046' => 'Бутонът изчезва от всяка страница за вход в тази среда, която го наследява. Данните за достъп се запазват, така че можете да го включите отново.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Бутонът изчезва от страницата за вход на тази организация — този на средата не го заменя. Данните за достъп се запазват, така че можете да го включите отново.',
    'the_console_is_pointed_at_this_environment_and_every_pa_4d2a0145' => 'Конзолата се насочва към тази среда и всяка страница, която отворите оттук нататък, чете нея вместо текущата. Нищо не се променя в нито една от двете.',
    'the_sign_in_page_your_people_see_is_yours_not_ours_logo_7573e3bf' => 'Страницата за вход използва идентичността на вашата организация: лого, цветове и текстове. Промените се виждат веднага в прегледа и важат за хостваната страница за вход на организацията.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Тези данни за достъп изискват одобрение от човек за това действие, но няма записан човек, който да го даде. Изпълнете действието от конзолата или издайте ключ от нея, за да може собственикът му да одобри.',
    'this_environment_falls_back_to_its_default_domain_every_201d6a2d' => 'Тази среда се връща към домейна си по подразбиране. Всеки клиент, фиксиран към текущия издател, URL за откриване или JWKS URL, спира да работи, докато не бъде пренасочен.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'Не успяхме да изпратим имейла в момента — тази инсталация няма връзка с пощенския си сървър. Опитайте по-късно; администратор може също да потвърди адреса ви с `php artisan cbox-id:users:confirm-email`.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Страницата ви за вход носи вашето лого и цветове. Хората въвеждат паролата си в нея — тя трябва да изглежда като ваша, не като наша.',
    'creating_an_app_issues_a_client_secret_shown_2840959a' => 'При създаването на приложение се издава таен ключ на клиента, който се показва само веднъж на следващия екран. Той удостоверява приложението, докато не бъде сменен с нов.',
    'registering_an_app_issues_a_client_secret_sh_631bb9f1' => 'При регистриране на приложение се създава клиентска тайна, която се показва само веднъж на следващия екран. Тя позволява удостоверяване от името на приложението, докато не бъде заменена.',
    'there_is_no_other_environment_in_this_projec_bfd62f34' => 'В този проект няма друга среда, която управлявате. Добавете такава към проекта или поискайте достъп до нея и тя ще се появи тук.',
    'this_app_belongs_to_an_organization_and_an_o_5487ac51' => 'Това приложение принадлежи на организация, а организацията съществува само в една среда. Изтеглете описанието му и го регистрирайте в другата среда под организацията, към която принадлежи там.',
    'this_app_registered_itself_so_it_is_not_one__ec7cea33' => 'Това приложение се е регистрирало само, затова не е сред собствените приложения на тази среда. Може да се регистрира по същия начин в другата среда.',
    'this_app_signs_in_with_its_own_keys_and_each_a40a0c9b' => 'Това приложение влиза със собствени ключове и всяка среда трябва да има свои. Изтеглете описанието му и го регистрирайте в другата среда с нейния набор от ключове.',
    'app_keys_unavailable_organization_switch' => 'Приложението, което ви изпрати тук, не предлага API ключове за организацията :organization. Опитайте с друга организация или се свържете с поддръжката на приложението.',
    'app_keys_unavailable_organization' => 'Приложението, което ви изпрати тук, не предлага API ключове за организацията :organization. Свържете се с поддръжката на приложението.',
    'app_keys_unavailable_switch' => 'Приложението, което ви изпрати тук, не предлага API ключове. Опитайте с друга организация или се свържете с поддръжката на приложението.',
    'app_keys_unavailable' => 'Приложението, което ви изпрати тук, не предлага API ключове. Свържете се с поддръжката на приложението.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Свържете се веднъж на най-горното ниво на платформата, вместо отделно за всяка среда. Влязъл от ваше име, агентът достига работното ви пространство, всички негови среди, които администрирате, и собствения ви акаунт. Инструмент за среда приема аргумент :part1 :part2, а REST API — заглавка :part3, указващи къде да се действа. Агентът може да прави каквото можете вие, в разрешените граници, а всяко критично действие чака одобрение на устройството ви.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Всяка организация дава на човека една роля от тип :part1, определяща какво може да администрира, и произволен брой роли от тип :part2, определящи действията му в приложенията.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Средата „:part1“ е създадена. Добавете :part2 от настройките за домейни на средата за проверка чрез DNS. Непотвърден домейн не може да бъде издател на средата.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'Средите принадлежат на проект, а проектът — на :part1 :part2 :part3. Започнете оттам, за да видите всички ресурси на организацията. Два вида записи никога нямат организация: :part4 е средата на самата инсталация, където са операторите и хората на организациите; среда с обозначение :part5 :part6 няма проект, затова не се фактурира и никоя организация не я достига. Нито едното е грешка за поправяне тук и този екран не променя принадлежността им.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Всички начини за вход в :part1, дали са включени и къде се променят. Организациите могат да затягат правилата: :part2 :part3.',
    'enter_it_to_turn_on_text_message_codes_1d7162aa' => 'Въведете го, за да включите кодовете чрез SMS.',
    'forty_of_them_type_to_narrow_eb4313eb' => 'Четиридесет са — започнете да пишете, за да стесните избора.',
    'four_variants_three_sizes_one_loading_state_a23b3bb3' => 'Четири варианта, три размера, едно състояние на зареждане.',
    'new_dashboard_is_on_for_acme_29525b4d' => 'Новото табло е включено за Acme.',
    'one_family_one_stroke_weight_add_to_resource_d89cf01e' => 'Едно семейство икони, една дебелина на линията. Добавете в resources/js/ui/icons.ts.',
    'rotating_after_the_leak_on_24_august_d5dbbc2b' => 'Ротация след изтичането на данни на 24 август',
    'they_can_also_be_given_the_link_directly_fac83540' => 'Връзката може да им бъде дадена и директно.',
    'this_endpoint_belongs_to_the_environment_you_1c2b35cf' => 'Тази крайна точка принадлежи на средата. Управлява я вашият оператор.',
    'this_organization_does_not_have_access_to_th_c472ad39' => 'Тази организация няма достъп до тази функция.',
    'this_page_has_expired_reload_it_and_try_agai_70dbb1a7' => 'Тази страница е изтекла. Презаредете я и опитайте отново.',
    'works_with_the_organization_s_apps_no_say_ov_9bb95fed' => 'Работи с приложенията на организацията; не управлява хората ѝ.',
    'you_appear_to_be_offline_check_your_connecti_0d700f8e' => 'Изглежда сте офлайн. Проверете връзката си и опитайте отново.',
    'you_do_not_have_permission_to_change_this_05d0ea6a' => 'Нямате разрешение да променяте това.',
    'you_do_not_run_this_deployment_a16652ca' => 'Не сте оператор на тази инсталация.',
    'your_account_is_not_a_member_of_an_organizat_79d48ca3' => 'Вашият акаунт не е член на организация.',
    'your_email_address_is_already_confirmed_285146dd' => 'Имейл адресът ви вече е потвърден.',
    'your_session_has_ended_sign_in_again_176c077e' => 'Сесията ви приключи. Влезте отново.',
    'confirm_action_for' => 'Потвърдете „:action“ за :name',
    'context_selection_label' => ':context: :name. Промяна на избора',
    'not_in_this_environment_98f2f096' => 'не е в тази среда',
