    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'В реда, в който хората ги виждат. Изключването на доставчик на средата тук само премахва бутона от тази страница; не спира входа чрез него другаде. За да е вашият доставчик единствената възможност, изискайте SSO в :part1 :part2.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Засегнатите хора (:part1) вече не могат да влизат в тази организация и приложенията, които разчитат на нея, спират да ги удостоверяват. Подорганизациите не се спират. Можете да активирате организацията отново тук.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Ключовете започват с този префикс, за да идентифицира приложението ключ, намерен в лог: :part1 :part2. Използвайте 2–16 малки букви или цифри, после :part3 или :part4 :part5, уникално за средата. Задаването включва ключовете; изчистването спира новите, но съществуващите работят до отнемане.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'Никой в тази организация не е създал ключ за приложенията ѝ. Хората създават собствени в Моят акаунт за приложение, което включва API ключове за членове в Настройки: :part1.',
