    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Когато някой се опита да влезе и е в състояние :part1, имейлът и паролата му се изпращат към тази крайна точка. Ако тя приеме входа, човекът се създава тук и данните повече не се изпращат там.',
