    'we_sent_a_link_to_part1_your_first_environment_your_liv_9786541d' => 'Изпратихме връзка до :part1. Първата ви среда — вашият производствен доставчик на идентичност със собствен вход, потребители и ключове за подписване — се създава, когато отворите връзката, след което се връщате директно тук. Връзката е валидна 24 часа.',
    'what_you_are_administering_and_the_details_your_apps_ne_23bc71ef' => 'Какво управлявате и какви данни са необходими на приложенията ви за интеграция. :part1',
    'which_of_its_actions_wait_for_a_person_the_agent_gets_a_e72df5dd' => 'Изберете кои действия да чакат одобрение от човек. Агентът получава отговор 202 с кратък код. Одобрявате на телефона или на :part1 :part2, след което агентът повтаря заявката само веднъж.',
