    'people_arrive_on_their_start_date_and_leave__69a0a1b9' => 'Хората се добавят в първия си работен ден и се премахват в последния според HR системата, която компанията вече поддържа.',
    'phones_enrolled_in_the_authenticator_app_the_c53bb961' => 'Телефони, регистрирани в приложението за удостоверяване. Получават подкани за одобрение и предупреждения, когато акаунтът ви влезе от ново място.',
    'pick_a_type_in_the_catalog_single_sign_on_di_9a947bbb' => 'Изберете тип от каталога — единен вход, синхронизиране на директория, HR система, уебкука, поток от журнали.',
    'push_your_people_into_another_app_over_its_s_7a73c970' => 'Изпращайте хората си в друго приложение чрез неговата крайна точка SCIM 2.0, така че добавянето и премахването на достъп да стават на едно място.',
    'runs_on_the_schedule_every_five_minutes_curs_830d7536' => 'Изпълнява се по график на всеки пет минути. С курсор и идемпотентно — изпращат се само записи след последната изпратена позиция.',
    'setting_up_the_authenticator_app_for_this_en_90ff9348' => 'Настройването на приложението за удостоверяване за тази среда не успя. Грешката е записана — презаредете страницата, за да опитате отново.',
    'ship_the_audit_trail_to_your_siem_or_cold_ar_b777e4b4' => 'Изпращайте одитната следа към своя SIEM или дългосрочен архив и изпълнявайте експорти на данни на субекти.',
    'the_most_recent_push_notifications_sent_to_t_cf468f18' => 'Най-скорошните насочени известия, изпратени до тези устройства, и причините за неуспешните',
