    'a_signed_message_to_your_endpoint_after_some_a8f5805d' => 'Подписано съобщение до крайната ви точка, след като нещо се случи — член се присъедини, роля се промени — за да реагират системите ви без периодични запитвания.',
    'an_app_that_accepts_this_environment_as_its__fe815b51' => 'Приложение, което приема тази среда за свой SAML доставчик на идентичност, така че потребителите ви влизат с акаунта си тук.',
    'an_organization_s_own_saml_or_oidc_identity__277b4568' => 'Собствен SAML или OIDC доставчик на идентичност на организация — Okta, Entra ID, Google Workspace — за да влизат хората ѝ със служебния си акаунт.',
    'every_kind_of_integration_this_platform_has__4b2a3ee2' => 'Всички видове интеграции на тази платформа. Настройте интеграция от картата ѝ или управлявайте наличните — всяка карта води към страницата на съответната интеграция.',
    'look_up_a_subject_s_audit_trail_actions_they_71f49e12' => 'Потърсете одитната следа на субекта — действията, които е извършил — за заявка за достъп в преносим формат. Изтриване не се предлага: заличаването на запис във верига от хешове би нарушило доказуемата ѝ цялост — вижте документацията.',
    'no_analytics_data_source_is_configured_or_re_1db9abb5' => 'Няма настроен или достъпен източник на аналитични данни. Когато платформата започне да записва използването — или бъде зададен ClickHouse DSN — активността ще се появи тук.',
    'people_connect_their_own_github_google_or_sl_261cd163' => 'Хората свързват собствените си акаунти в GitHub, Google или Slack, а приложенията, на които дадете достъп, извикват тези API от тяхно име с токен, поддържан актуален тук.',
    'this_link_expires_after_two_minutes_and_only_2009db22' => 'Тази връзка изтича след две минути и работи само веднъж, за вашия акаунт. Обновява се сама, докато страницата е отворена — не споделяйте нейна снимка на екрана.',
